// Export de contenu IA (résumés, corrigés, quiz…) en Word, Excel, PDF et WhatsApp.
// Word/Excel : génération HTML native (aucune librairie).
// PDF : jsPDF chargé depuis un CDN (compatible navigateur).

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const safeName = (s) => String(s || 'document')
  .replace(/[^a-z0-9]+/gi, '_').slice(0, 40) || 'document';

const download = (blob, filename) => {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
};

/** Export Word (.doc) — Word ouvre nativement le HTML balisé. */
export function exportWord(titre, contenu) {
  const corps = esc(contenu).replace(/\n/g, '<br>');
  const html =
    `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word'>` +
    `<head><meta charset='utf-8'><title>${esc(titre)}</title></head>` +
    `<body style="font-family:Calibri,Arial,sans-serif;font-size:12pt;color:#1a1a1a;line-height:1.5">` +
    `<h1 style="color:#0EA5E9">${esc(titre)}</h1>` +
    `<div>${corps}</div>` +
    `<hr><p style="font-size:9pt;color:#888">Généré avec RevisIA_H24</p>` +
    `</body></html>`;
  download(new Blob(['﻿', html], { type: 'application/msword' }), `${safeName(titre)}.doc`);
}

/** Export Excel (.xls) — chaque ligne du contenu = une ligne du tableau. */
export function exportExcel(titre, contenu) {
  const lignes = String(contenu).split('\n').filter(l => l.trim());
  const rows = lignes.map(l => `<tr><td>${esc(l)}</td></tr>`).join('');
  const html =
    `<html><head><meta charset='utf-8'></head><body>` +
    `<table border='1'><tr><th style="background:#0EA5E9;color:#fff">${esc(titre)}</th></tr>${rows}</table>` +
    `</body></html>`;
  download(new Blob(['﻿', html], { type: 'application/vnd.ms-excel' }), `${safeName(titre)}.xls`);
}

/** Charge jsPDF depuis un CDN. */
const chargerJsPDF = () => new Promise((resolve, reject) => {
  if (window.jspdf?.jsPDF) return resolve(window.jspdf.jsPDF);
  const s = document.createElement('script');
  s.src = 'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
  s.onload = () => resolve(window.jspdf?.jsPDF);
  s.onerror = () => reject(new Error('PDF indisponible'));
  document.head.appendChild(s);
});

/** Export PDF avec pagination automatique du texte. */
export async function exportPDF(titre, contenu) {
  const jsPDF = await chargerJsPDF();
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const margeX = 15, largeur = 180;
  let y = 20;

  doc.setFontSize(16); doc.setTextColor(14, 165, 233);
  doc.text(doc.splitTextToSize(titre, largeur), margeX, y);
  y += 12;

  doc.setFontSize(11); doc.setTextColor(30, 30, 30);
  const lignes = doc.splitTextToSize(String(contenu), largeur);
  lignes.forEach(ligne => {
    if (y > 280) { doc.addPage(); y = 20; }
    doc.text(ligne, margeX, y);
    y += 6;
  });

  doc.setFontSize(8); doc.setTextColor(150);
  doc.text('Généré avec RevisIA_H24', margeX, 290);
  doc.save(`${safeName(titre)}.pdf`);
}

/**
 * Copie le contenu dans le presse-papier.
 * Retourne true si réussi.
 */
export async function copyToClipboard(contenu) {
  try {
    await navigator.clipboard.writeText(String(contenu));
    return true;
  } catch {
    // Fallback pour les anciens navigateurs / WebView sans permissions
    const el = document.createElement('textarea');
    el.value = String(contenu);
    el.style.position = 'fixed'; el.style.opacity = '0';
    document.body.appendChild(el);
    el.select();
    document.execCommand('copy');
    document.body.removeChild(el);
    return true;
  }
}

/**
 * Partage sur WhatsApp.
 * Fonctionne sur mobile APK (deep link whatsapp://) et web (wa.me).
 */
export function shareWhatsApp(titre, contenu) {
  // Limiter à 4000 caractères (limite WhatsApp)
  const MAX = 3800;
  let text = `*${titre}*\n\n${String(contenu)}`;
  if (text.length > MAX) {
    text = text.slice(0, MAX) + '\n\n...(suite dans RevisIA_H24)';
  }
  text += '\n\n_✨ Généré avec RevisIA_H24_';
  const encoded = encodeURIComponent(text);

  // Sur Android APK (Capacitor) → ouvre l'app WhatsApp directement
  // Sur navigateur web → ouvre WhatsApp Web
  const isCapacitor = window.Capacitor?.isNativePlatform?.() || false;
  if (isCapacitor) {
    window.open(`whatsapp://send?text=${encoded}`, '_system');
  } else {
    window.open(`https://wa.me/?text=${encoded}`, '_blank', 'noopener');
  }
}

/**
 * Partage générique (Web Share API ou fallback WhatsApp).
 */
export async function shareResult(titre, contenu) {
  if (navigator.share) {
    try {
      await navigator.share({ title: titre, text: contenu });
      return;
    } catch (e) {
      if (e.name !== 'AbortError') shareWhatsApp(titre, contenu);
      return;
    }
  }
  shareWhatsApp(titre, contenu);
}
