import React, { useState } from 'react';
import { useToast } from '../hooks/useToast';
import { FileText, FileSpreadsheet, FileDown, Copy, Check, MessageCircle } from 'lucide-react';
import { exportWord, exportExcel, exportPDF, copyToClipboard, shareWhatsApp } from '../utils/exportUtils';

/**
 * Boutons d'export d'un contenu IA en Word / Excel / PDF / WhatsApp + Copier.
 * Props : titre (string), contenu (string), compact (bool)
 */
const ExportButtons = ({ titre = 'Document RevisIA_H24', contenu = '', compact = false }) => {
  const { showToast, ToastUI } = useToast();
  const [busy, setBusy]       = useState('');
  const [copied, setCopied]   = useState(false);

  if (!contenu || !String(contenu).trim()) return null;

  const handle = async (type, fn) => {
    setBusy(type);
    try { await fn(titre, contenu); } catch (e) { showToast('Export impossible. Réessaie.', 'error'); }
    finally { setBusy(''); }
  };

  const handleCopy = async () => {
    await copyToClipboard(contenu);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleWhatsApp = () => shareWhatsApp(titre, contenu);

  const base = {
    display: 'inline-flex', alignItems: 'center', gap: 5,
    padding: compact ? '5px 9px' : '7px 13px',
    borderRadius: 9, border: 'none',
    cursor: 'pointer', fontWeight: 700,
    fontSize: compact ? '0.72rem' : '0.78rem',
    transition: 'all 0.15s',
    whiteSpace: 'nowrap',
  };

  return (
    <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center', marginTop: 10 }}>
      {ToastUI}
      <span style={{ color: '#475569', fontSize: '0.65rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', flexShrink: 0 }}>
        Exporter :
      </span>

      {/* ─── Copier ─── */}
      <button onClick={handleCopy}
        style={{ ...base, background: copied ? 'rgba(16,185,129,0.12)' : '#f1f5f9', color: copied ? '#10B981' : '#64748b' }}
        title="Copier dans le presse-papier">
        {copied ? <Check size={13} /> : <Copy size={13} />}
        {copied ? 'Copié !' : 'Copier'}
      </button>

      {/* ─── WhatsApp ─── */}
      <button onClick={handleWhatsApp}
        style={{ ...base, background: 'rgba(37,211,102,0.15)', color: '#25D366' }}
        title="Partager sur WhatsApp">
        <MessageCircle size={13} />
        WhatsApp
      </button>

      {/* ─── Word ─── */}
      <button onClick={() => handle('word', exportWord)} disabled={!!busy}
        style={{ ...base, background: 'rgba(37,99,235,0.12)', color: '#60A5FA' }}
        title="Télécharger en Word (.doc)">
        <FileText size={13} /> {busy === 'word' ? '…' : 'Word'}
      </button>

      {/* ─── PDF ─── */}
      <button onClick={() => handle('pdf', exportPDF)} disabled={!!busy}
        style={{ ...base, background: 'rgba(239,68,68,0.12)', color: '#F87171' }}
        title="Télécharger en PDF">
        <FileDown size={13} /> {busy === 'pdf' ? '…' : 'PDF'}
      </button>

      {/* ─── Excel ─── */}
      <button onClick={() => handle('excel', exportExcel)} disabled={!!busy}
        style={{ ...base, background: 'rgba(16,185,129,0.12)', color: '#34D399' }}
        title="Télécharger en Excel (.xls)">
        <FileSpreadsheet size={13} /> {busy === 'excel' ? '…' : 'Excel'}
      </button>
    </div>
  );
};

export default ExportButtons;
