import React from 'react';
import { motion } from 'framer-motion';
import { Sparkles } from 'lucide-react';
import AnimatedBackground from './AnimatedBackground';

/**
 * Écran de chargement animé de marque RevisIA_H24.
 * Usage : if (loading) return <BrandedLoader message="Chargement…" variant="blue" />;
 */
const BrandedLoader = ({ message = 'Chargement…', variant = 'blue', fullscreen = true }) => {
  const accent = {
    blue:   '#38BDF8',
    green:  '#10B981',
    purple: '#8B5CF6',
    orange: '#F97316',
  }[variant] || '#38BDF8';

  return (
    <div style={{
      position: fullscreen ? 'fixed' : 'relative',
      inset: fullscreen ? 0 : undefined,
      minHeight: fullscreen ? '100vh' : '320px',
      width: '100%',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      background: '#070C18',
      overflow: 'hidden',
      zIndex: fullscreen ? 9999 : 1,
    }}>
      <AnimatedBackground variant={variant} intensity={0.6} />

      <div style={{ position: 'relative', zIndex: 2, textAlign: 'center' }}>
        {/* Logo pulsant entouré d'un anneau qui tourne */}
        <div style={{ position: 'relative', width: 96, height: 96, margin: '0 auto 1.5rem' }}>
          <motion.div
            animate={{ rotate: 360 }}
            transition={{ duration: 1.4, repeat: Infinity, ease: 'linear' }}
            style={{
              position: 'absolute', inset: 0,
              borderRadius: '50%',
              border: `3px solid ${accent}22`,
              borderTopColor: accent,
            }}
          />
          <motion.div
            animate={{ scale: [1, 1.12, 1], opacity: [0.85, 1, 0.85] }}
            transition={{ duration: 1.8, repeat: Infinity, ease: 'easeInOut' }}
            style={{
              position: 'absolute', inset: '18px',
              borderRadius: '22px',
              background: `linear-gradient(135deg, ${accent}, #8B5CF6)`,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              boxShadow: `0 0 30px ${accent}66`,
            }}
          >
            <Sparkles size={28} color="white" />
          </motion.div>
        </div>

        <motion.h2
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          style={{
            margin: 0, fontSize: '1.3rem', fontWeight: 800, letterSpacing: '0.5px',
            color: 'white', fontFamily: 'Outfit, sans-serif',
          }}
        >
          Revis<span style={{ color: accent }}>IA</span>_H24
        </motion.h2>

        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: [0.4, 1, 0.4] }}
          transition={{ duration: 1.6, repeat: Infinity }}
          style={{ marginTop: '0.6rem', color: '#475569', fontSize: '0.9rem' }}
        >
          {message}
        </motion.p>

        {/* Barre de progression indéterminée */}
        <div style={{
          marginTop: '1.4rem', width: '200px', height: '4px',
          background: '#e2e8f0', borderRadius: '4px',
          overflow: 'hidden', marginLeft: 'auto', marginRight: 'auto',
        }}>
          <motion.div
            animate={{ x: ['-100%', '250%'] }}
            transition={{ duration: 1.3, repeat: Infinity, ease: 'easeInOut' }}
            style={{
              width: '40%', height: '100%', borderRadius: '4px',
              background: `linear-gradient(90deg, transparent, ${accent}, transparent)`,
            }}
          />
        </div>
      </div>
    </div>
  );
};

export default BrandedLoader;
