import React, { useState } from 'react';
import { AlertCircle, CheckCircle, Loader, Send, Image, FileText } from 'lucide-react';
import { submissionsAPI, fileAPI, BACKEND_BASE_URL } from '../services/api';

/**
 * SubmissionForm - Permet aux étudiants de soumettre pour correction
 * Avec fichier de l'épreuve + image de la réponse
 */
const SubmissionForm = ({ epreuveId, epreuveTitle, user, onSubmitted }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const [formData, setFormData] = useState({
    fichierEpreuve: '',
    imageSolution: '',
    commentaires: ''
  });
  const [uploadingEpreuve, setUploadingEpreuve] = useState(false);
  const [uploadingSolution, setUploadingSolution] = useState(false);
  const [epreuveFileName, setEpreuveFileName] = useState('');
  const [solutionFileName, setSolutionFileName] = useState('');

  const resolveUploadedUrl = (res) => {
    const url = res.data?.url || res.data?.path || res.data;
    return typeof url === 'string' && url.startsWith('http') ? url : `${BACKEND_BASE_URL}${url}`;
  };

  const handleFilePick = async (e, field) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const setUploading = field === 'fichierEpreuve' ? setUploadingEpreuve : setUploadingSolution;
    const setFileName = field === 'fichierEpreuve' ? setEpreuveFileName : setSolutionFileName;
    try {
      setUploading(true);
      setError('');
      const fd = new FormData();
      fd.append('file', file);
      const res = await fileAPI.uploadFile(fd);
      const fullUrl = resolveUploadedUrl(res);
      setFormData((prev) => ({ ...prev, [field]: fullUrl }));
      setFileName(file.name);
    } catch {
      setError(field === 'fichierEpreuve'
        ? 'Échec de l\'upload du fichier de l\'épreuve'
        : 'Échec de l\'upload de l\'image de réponse');
    } finally {
      setUploading(false);
    }
  };

  const resetForm = () => {
    setFormData({ fichierEpreuve: '', imageSolution: '', commentaires: '' });
    setEpreuveFileName('');
    setSolutionFileName('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.fichierEpreuve) {
      setError('Le fichier de l\'épreuve est requis');
      return;
    }

    try {
      setLoading(true);
      setError('');

      const res = await submissionsAPI.soumettrePourCorrection({
        epreuveId,
        fichierEpreuve: formData.fichierEpreuve,
        imageSolution: formData.imageSolution,
        commentaires: formData.commentaires
      });

      setSuccess('✅ Soumission envoyée avec succès!');
      setSubmitted(true);
      resetForm();

      if (onSubmitted) {
        onSubmitted(res.data);
      }

      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError('Erreur lors de la soumission');
    } finally {
      setLoading(false);
    }
  };

  if (submitted) {
    return (
      <div style={{
        background: '#f0fdf4',
        border: '1px solid #86efac',
        borderRadius: '12px',
        padding: '20px',
        textAlign: 'center'
      }}>
        <CheckCircle size={48} style={{ color: '#10b981', margin: '0 auto 15px', display: 'block' }} />
        <h3 style={{ margin: '0 0 10px 0', color: '#047857', fontSize: '1.1rem', fontWeight: 700 }}>
          ✅ Soumission Reçue
        </h3>
        <p style={{ margin: '0 0 15px 0', color: '#065f46' }}>
          Votre soumission pour <strong>{epreuveTitle}</strong> a été enregistrée.
          Votre professeur la corrigera et vous enverrez un retour.
        </p>
        <button
          onClick={() => setSubmitted(false)}
          style={{
            background: '#10b981',
            color: 'white',
            border: 'none',
            padding: '10px 20px',
            borderRadius: '8px',
            cursor: 'pointer',
            fontWeight: 600
          }}
        >
          Soumettre à nouveau
        </button>
      </div>
    );
  }

  return (
    <div style={{
      background: 'white',
      border: '1px solid #e5e7eb',
      borderRadius: '12px',
      padding: '20px'
    }}>
      <div style={{ marginBottom: '20px' }}>
        <h3 style={{ margin: '0 0 5px 0', fontSize: '1.1rem', fontWeight: 700 }}>
          📤 Soumettre pour Correction
        </h3>
        <p style={{ margin: '0', color: '#666', fontSize: '0.9rem' }}>
          Uploadez votre fichier de l'épreuve et votre réponse (image/photo)
        </p>
      </div>

      {error && (
        <div style={{
          background: '#fee',
          padding: '12px 15px',
          borderRadius: '8px',
          marginBottom: '15px',
          color: '#c33',
          display: 'flex',
          gap: '10px',
          alignItems: 'flex-start'
        }}>
          <AlertCircle size={18} style={{ flexShrink: 0, marginTop: '2px' }} />
          <div>{error}</div>
        </div>
      )}

      {success && (
        <div style={{
          background: '#f0fdf4',
          padding: '12px 15px',
          borderRadius: '8px',
          marginBottom: '15px',
          color: '#10b981',
          display: 'flex',
          gap: '10px',
          alignItems: 'flex-start'
        }}>
          <CheckCircle size={18} style={{ flexShrink: 0, marginTop: '2px' }} />
          <div>{success}</div>
        </div>
      )}

      <form onSubmit={handleSubmit}>
        {/* Fichier de l'épreuve */}
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 600, marginBottom: '8px' }}>
            <FileText size={18} style={{ color: '#3b82f6' }} />
            Fichier de l'épreuve *
          </label>
          <p style={{ margin: '0 0 8px 0', color: '#666', fontSize: '0.9rem' }}>
            Uploadez le fichier ou l'image du sujet de l'épreuve
          </p>
          <input
            type="file"
            accept=".pdf,.doc,.docx,.ppt,.pptx,.png,.jpg,.jpeg,.webp"
            onChange={(e) => handleFilePick(e, 'fichierEpreuve')}
            disabled={uploadingEpreuve}
            style={{
              width: '100%',
              padding: '12px',
              border: '2px dashed #3b82f6',
              borderRadius: '8px',
              boxSizing: 'border-box',
              fontFamily: 'inherit',
              fontSize: '0.9rem'
            }}
            required={!formData.fichierEpreuve}
          />
          {uploadingEpreuve && (
            <p style={{ margin: '6px 0 0', fontSize: '0.85rem', color: '#666' }}>Upload en cours…</p>
          )}
          {formData.fichierEpreuve && !uploadingEpreuve && (
            <p style={{ margin: '6px 0 0', fontSize: '0.85rem', color: '#10b981' }}>
              ✓ {epreuveFileName || 'Fichier prêt'}
            </p>
          )}
        </div>

        {/* Image/Photo de la réponse */}
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 600, marginBottom: '8px' }}>
            <Image size={18} style={{ color: '#10b981' }} />
            Image/Photo de votre réponse (optionnel)
          </label>
          <p style={{ margin: '0 0 8px 0', color: '#666', fontSize: '0.9rem' }}>
            Uploadez une photo de votre copie écrite ou une capture d'écran de votre réponse
          </p>
          <input
            type="file"
            accept="image/*,.pdf"
            onChange={(e) => handleFilePick(e, 'imageSolution')}
            disabled={uploadingSolution}
            style={{
              width: '100%',
              padding: '12px',
              border: '2px dashed #10b981',
              borderRadius: '8px',
              boxSizing: 'border-box',
              fontFamily: 'inherit',
              fontSize: '0.9rem'
            }}
          />
          {uploadingSolution && (
            <p style={{ margin: '6px 0 0', fontSize: '0.85rem', color: '#666' }}>Upload en cours…</p>
          )}
          {formData.imageSolution && !uploadingSolution && (
            <p style={{ margin: '6px 0 0', fontSize: '0.85rem', color: '#10b981' }}>
              ✓ {solutionFileName || 'Fichier prêt'}
            </p>
          )}
        </div>

        {/* Commentaires */}
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', fontWeight: 600, marginBottom: '8px' }}>
            💬 Commentaires additionnels (optionnel)
          </label>
          <textarea
            placeholder="Ex: J'ai eu des difficultés avec la partie 2... Ou: Voici ma réponse avec les étapes..."
            value={formData.commentaires}
            onChange={(e) => setFormData({ ...formData, commentaires: e.target.value })}
            rows="4"
            style={{
              width: '100%',
              padding: '12px',
              border: '1px solid #ddd',
              borderRadius: '8px',
              boxSizing: 'border-box',
              fontFamily: 'inherit',
              resize: 'vertical'
            }}
          />
        </div>

        {/* Boutons */}
        <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
          <button
            type="button"
            onClick={resetForm}
            style={{
              padding: '10px 20px',
              background: '#f0f0f0',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              fontWeight: 600,
              transition: 'all 0.2s'
            }}
            onMouseEnter={(e) => e.target.style.background = '#e0e0e0'}
            onMouseLeave={(e) => e.target.style.background = '#f0f0f0'}
          >
            Réinitialiser
          </button>
          <button
            type="submit"
            disabled={loading || uploadingEpreuve || uploadingSolution || !formData.fichierEpreuve}
            style={{
              padding: '10px 20px',
              background: loading ? '#ccc' : '#3b82f6',
              color: 'white',
              border: 'none',
              borderRadius: '8px',
              cursor: loading ? 'not-allowed' : 'pointer',
              fontWeight: 600,
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              transition: 'all 0.2s'
            }}
            onMouseEnter={(e) => !loading && (e.target.style.background = '#2563eb')}
            onMouseLeave={(e) => !loading && (e.target.style.background = '#3b82f6')}
          >
            {loading ? (
              <>
                <Loader size={18} className="spinner" />
                Soumission en cours...
              </>
            ) : (
              <>
                <Send size={18} />
                Soumettre pour Correction
              </>
            )}
          </button>
        </div>
      </form>

      <style jsx>{`
        .spinner {
          animation: spin 1s linear infinite;
        }
        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default SubmissionForm;
