import React, { useState, useRef } from 'react';
import { useToast } from '../hooks/useToast';
import {
  MessageCircle, HelpCircle, BookOpen, Zap, FileText, CheckCircle,
  Loader, Send, Upload, Camera, X, Paperclip, ChevronDown
} from 'lucide-react';
import { aiAPI } from '../services/api';
import '../styles/StudentAIPanel.css';

/**
 * Panel IA complet pour les étudiants
 * ✅ Lecture de fichiers via Python AI service (PDF, images, Word, PPT, Excel...)
 * ✅ 6 onglets: Chat, Expliquer, Quiz, Résoudre, Résumer, Corriger
 */

const FORMATS_ACCEPTES = '.pdf,.docx,.doc,.pptx,.ppt,.xlsx,.xls,.png,.jpg,.jpeg,.webp,.gif,.txt';
const TYPES_VALIDES = [
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'application/vnd.ms-powerpoint',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.ms-excel',
  'image/jpeg', 'image/png', 'image/gif', 'image/webp', 'image/bmp',
  'text/plain', 'text/csv',
];

export default function StudentAIPanel({ student }) {
  const { showToast, ToastUI } = useToast();
  const [activeTab, setActiveTab] = useState('chat');
  const [loading, setLoading] = useState(false);
  const [response, setResponse] = useState(null);
  const [input, setInput] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const [difficulty, setDifficulty] = useState('L2');
  const [showDiffMenu, setShowDiffMenu] = useState(false);

  const fileInputRef = useRef(null);
  const cameraInputRef = useRef(null);

  // ── Validation fichier ──────────────────────────────────────────────────────
  const validerFichier = (file) => {
    const sizeInMB = file.size / (1024 * 1024);
    if (sizeInMB > 19) {
      showToast(`⚠️ Fichier trop grand (${sizeInMB.toFixed(1)} MB). Maximum: 19 MB.`, 'warning');
      return false;
    }
    if (file.type && !TYPES_VALIDES.includes(file.type) && !file.name.match(/\.(pdf|docx?|pptx?|xlsx?|png|jpe?g|webp|gif|txt|csv)$/i)) {
      showToast(`⚠️ Format non supporté: ${file.name}. Acceptés: PDF, Word, PowerPoint, Excel, Images, Texte`, 'warning');
      return false;
    }
    return true;
  };

  const handleFileSelect = (e) => {
    const file = e.target.files?.[0];
    if (file && validerFichier(file)) {
      setSelectedFile(file);
      setResponse(null);
    }
    e.target.value = '';
  };

  const clearFile = () => setSelectedFile(null);

  // ── 1. CHAT avec fichier optionnel ─────────────────────────────────────────
  const handleChat = async () => {
    if (!input.trim() && !selectedFile) {
      showToast('Posez une question ou joignez un fichier', 'warning');
      return;
    }
    setLoading(true);
    setResponse(null);
    try {
      const form = new FormData();
      form.append('question', input || 'Analyse ce document et explique son contenu.');
      form.append('contexte_profil', `Étudiant ${difficulty} — ${student?.nomComplet || 'Étudiant'}`);
      if (selectedFile) form.append('file', selectedFile);

      // ✅ Utilise le service Python IA (qui lit vraiment les fichiers)
      const res = await aiAPI.chat(form);
      setResponse({ type: 'chat', content: res.data?.answer || res.data?.text || '❌ Réponse vide.' });
      setInput('');
      setSelectedFile(null);
    } catch (err) {
      setResponse({ type: 'error', content: '❌ ' + (err.response?.data?.error || err.message || 'Erreur réseau') });
    } finally {
      setLoading(false);
    }
  };

  // ── 2. EXPLIQUER un concept ────────────────────────────────────────────────
  const handleExplain = async () => {
    if (!input.trim() && !selectedFile) {
      showToast('Entrez un concept à expliquer ou joignez un document', 'warning');
      return;
    }
    setLoading(true);
    setResponse(null);
    try {
      const form = new FormData();
      form.append('question', input
        ? `Explique clairement le concept suivant pour un étudiant de niveau ${difficulty}: ${input}`
        : `Explique le contenu de ce document de façon claire et pédagogique pour un étudiant niveau ${difficulty}.`
      );
      form.append('contexte_profil', `Étudiant ${difficulty}`);
      if (selectedFile) form.append('file', selectedFile);

      const res = await aiAPI.chat(form);
      setResponse({ type: 'explain', content: res.data?.answer || '❌ Réponse vide.' });
      setInput('');
      setSelectedFile(null);
    } catch (err) {
      setResponse({ type: 'error', content: '❌ ' + (err.response?.data?.error || err.message) });
    } finally {
      setLoading(false);
    }
  };

  // ── 3. QUIZ ────────────────────────────────────────────────────────────────
  const handleQuiz = async () => {
    if (!input.trim() && !selectedFile) {
      showToast('Entrez un sujet ou joignez un document', 'warning');
      return;
    }
    setLoading(true);
    setResponse(null);
    try {
      const form = new FormData();
      form.append('sujet', input || 'le document fourni');
      form.append('niveau', difficulty);
      form.append('numQuestions', '5');
      if (selectedFile) form.append('file', selectedFile);

      // ✅ Service Python IA — génère un vrai quiz depuis le fichier
      const res = await aiAPI.generateQuiz(form);
      const data = res.data;
      if (data?.questions?.length) {
        setResponse({ type: 'quiz', questions: data.questions, titre: data.titre || `Quiz — ${input}` });
      } else {
        setResponse({ type: 'quiz', content: data?.raw || '❌ Quiz vide. Réessayez.' });
      }
      setInput('');
      setSelectedFile(null);
    } catch (err) {
      setResponse({ type: 'error', content: '❌ ' + (err.response?.data?.error || err.message) });
    } finally {
      setLoading(false);
    }
  };

  // ── 4. RÉSOUDRE pas à pas ──────────────────────────────────────────────────
  const handleSolve = async () => {
    if (!input.trim() && !selectedFile) {
      showToast("Décrivez le problème ou joignez une feuille d'exercices", 'warning');
      return;
    }
    setLoading(true);
    setResponse(null);
    try {
      const form = new FormData();
      form.append('question', input
        ? `Résous ce problème étape par étape, en expliquant chaque étape clairement: ${input}`
        : `Résous les exercices/problèmes de ce document étape par étape, en expliquant chaque étape.`
      );
      form.append('contexte_profil', `Étudiant ${difficulty} — résolution pas à pas`);
      if (selectedFile) form.append('file', selectedFile);

      const res = await aiAPI.chat(form);
      setResponse({ type: 'solve', content: res.data?.answer || '❌ Réponse vide.' });
      setInput('');
      setSelectedFile(null);
    } catch (err) {
      setResponse({ type: 'error', content: '❌ ' + (err.response?.data?.error || err.message) });
    } finally {
      setLoading(false);
    }
  };

  // ── 5. RÉSUMER un document ─────────────────────────────────────────────────
  const handleSummarize = async () => {
    if (!selectedFile && !input.trim()) {
      showToast('Joignez un fichier (PDF, Word, image...) ou tapez du texte à résumer', 'warning');
      return;
    }
    setLoading(true);
    setResponse(null);
    try {
      const form = new FormData();
      form.append('titre_cours', input || selectedFile?.name || 'Document');
      form.append('matiere_nom', '');
      if (selectedFile) form.append('file', selectedFile);

      // ✅ Service Python IA — lit vraiment le PDF/Word/image et résume
      const res = await aiAPI.summarizeCourse(form);
      setResponse({
        type: 'summarize',
        content: res.data?.summary || res.data?.answer || '❌ Résumé vide.',
        filename: selectedFile?.name
      });
      setSelectedFile(null);
      setInput('');
    } catch (err) {
      setResponse({ type: 'error', content: '❌ ' + (err.response?.data?.error || 'Erreur résumé') });
    } finally {
      setLoading(false);
    }
  };

  // ── 6. CORRIGER un travail ─────────────────────────────────────────────────
  const handleCorrect = async () => {
    if (!selectedFile) {
      showToast("Joignez votre devoir, rapport ou feuille d'examen (PDF, image, Word...)", 'warning');
      return;
    }
    setLoading(true);
    setResponse(null);
    try {
      const form = new FormData();
      form.append('nom_fichier', selectedFile.name);
      form.append('titre_cours', input || '');
      form.append('matiere_nom', '');
      form.append('file', selectedFile);

      // ✅ Service Python IA — corrige l'épreuve/devoir avec feedback détaillé
      const res = await aiAPI.correctExam(form);
      setResponse({
        type: 'correct',
        content: res.data?.correction || res.data?.feedback || '❌ Correction vide.',
        filename: selectedFile.name
      });
      setSelectedFile(null);
      setInput('');
    } catch (err) {
      setResponse({ type: 'error', content: '❌ ' + (err.response?.data?.error || 'Erreur correction') });
    } finally {
      setLoading(false);
    }
  };

  // ── Map onglet → action ────────────────────────────────────────────────────
  const TABS = [
    { id: 'chat',      icon: <MessageCircle size={18}/>, label: 'Chat',      action: handleChat,      hint: 'Question + fichier optionnel' },
    { id: 'explain',   icon: <HelpCircle size={18}/>,    label: 'Expliquer', action: handleExplain,   hint: 'Concept ou document à expliquer' },
    { id: 'quiz',      icon: <Zap size={18}/>,           label: 'Quiz',      action: handleQuiz,      hint: 'Générer quiz depuis sujet ou fichier' },
    { id: 'solve',     icon: <BookOpen size={18}/>,      label: 'Résoudre',  action: handleSolve,     hint: 'Problème/exercice étape par étape' },
    { id: 'summarize', icon: <FileText size={18}/>,      label: 'Résumer',   action: handleSummarize, hint: 'Résumer un cours, PDF ou image' },
    { id: 'correct',   icon: <CheckCircle size={18}/>,   label: 'Corriger',  action: handleCorrect,   hint: 'Corriger un devoir ou une épreuve' },
  ];

  const currentTab = TABS.find(t => t.id === activeTab);

  return (
    <div className="student-ai-panel">
      {ToastUI}
      {/* ── Header ─────────────────────────────────────────────────────────── */}
      <div className="ai-header">
        <h2>🤖 Assistant IA Académique</h2>
        <p>Posez des questions, résumez vos cours, générez des quiz, corrigez vos travaux</p>
        <p style={{ fontSize: '0.75rem', color: '#475569', marginTop: 4 }}>
          ✅ Lit les PDF, images, Word, PowerPoint, Excel
        </p>
      </div>

      {/* ── Tabs ───────────────────────────────────────────────────────────── */}
      <div className="ai-tabs-container">
        {TABS.map(tab => (
          <button
            key={tab.id}
            className={`ai-tab ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => { setActiveTab(tab.id); setResponse(null); }}
            title={tab.hint}
          >
            {tab.icon}
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      {/* ── Zone saisie + fichier ───────────────────────────────────────────── */}
      <div className="ai-input-zone">
        {/* Inputs fichier (caché) */}
        <input ref={fileInputRef} type="file" accept={FORMATS_ACCEPTES} onChange={handleFileSelect} style={{ display: 'none' }} />
        <input ref={cameraInputRef} type="file" accept="image/*" capture="environment" onChange={handleFileSelect} style={{ display: 'none' }} />

        {/* Indicateur fichier sélectionné */}
        {selectedFile && (
          <div style={{
            display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px',
            background: 'rgba(56,189,248,0.1)', border: '1px solid rgba(56,189,248,0.3)',
            borderRadius: 10, marginBottom: 10, fontSize: '0.82rem', color: '#38BDF8'
          }}>
            <FileText size={16} />
            <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {selectedFile.name} ({(selectedFile.size / 1024 / 1024).toFixed(1)} MB)
            </span>
            <button onClick={clearFile} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#475569', padding: 2 }}>
              <X size={14} />
            </button>
          </div>
        )}

        {/* Textarea + boutons fichier */}
        <div style={{ display: 'flex', gap: 8, alignItems: 'flex-end' }}>
          <div style={{ flex: 1 }}>
            <textarea
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); currentTab?.action(); } }}
              placeholder={currentTab?.hint || 'Tapez votre question...'}
              rows={3}
              style={{
                width: '100%', background: '#f1f5f9',
                border: '1px solid rgba(255,255,255,0.12)', borderRadius: 12,
                padding: '10px 14px', color: '#F1F5F9', fontSize: '0.88rem',
                resize: 'vertical', outline: 'none', fontFamily: 'inherit',
                boxSizing: 'border-box'
              }}
            />
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            {/* Bouton fichier */}
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              title="Joindre un fichier (PDF, Word, image...)"
              style={{ padding: '10px', borderRadius: 10, border: '1px solid rgba(255,255,255,0.12)', background: '#f1f5f9', color: '#475569', cursor: 'pointer' }}
            >
              <Paperclip size={18} />
            </button>
            {/* Bouton caméra */}
            <button
              type="button"
              onClick={() => cameraInputRef.current?.click()}
              title="Prendre une photo"
              style={{ padding: '10px', borderRadius: 10, border: '1px solid rgba(168,85,247,0.3)', background: 'rgba(168,85,247,0.08)', color: '#A855F7', cursor: 'pointer' }}
            >
              <Camera size={18} />
            </button>
          </div>
        </div>

        {/* Ligne boutons action + niveau */}
        <div style={{ display: 'flex', gap: 8, marginTop: 10, alignItems: 'center' }}>
          {/* Bouton envoyer */}
          <button
            onClick={currentTab?.action}
            disabled={loading}
            style={{
              flex: 1, padding: '12px 16px', borderRadius: 12, border: 'none',
              background: loading ? 'rgba(100,116,139,0.3)' : 'linear-gradient(135deg, #3B82F6, #8B5CF6)',
              color: 'white', fontWeight: 800, cursor: loading ? 'not-allowed' : 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
              fontSize: '0.9rem', transition: 'all 0.2s'
            }}
          >
            {loading ? <><Loader size={18} style={{ animation: 'spin 1s linear infinite' }} /> Traitement...</> : <><Send size={18} /> {currentTab?.label}</>}
          </button>

          {/* Sélecteur niveau */}
          <div style={{ position: 'relative' }}>
            <button
              onClick={() => setShowDiffMenu(!showDiffMenu)}
              style={{ padding: '10px 14px', borderRadius: 12, border: '1px solid rgba(255,255,255,0.12)', background: '#f1f5f9', color: '#334155', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6, fontWeight: 700, fontSize: '0.82rem', whiteSpace: 'nowrap' }}
            >
              {difficulty} <ChevronDown size={14} />
            </button>
            {showDiffMenu && (
              <div style={{ position: 'absolute', bottom: '110%', right: 0, background: '#1E293B', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 10, overflow: 'hidden', zIndex: 100, minWidth: 90 }}>
                {['L1','L2','L3','M1','M2'].map(lvl => (
                  <button key={lvl} onClick={() => { setDifficulty(lvl); setShowDiffMenu(false); }}
                    style={{ display: 'block', width: '100%', padding: '8px 14px', background: difficulty === lvl ? 'rgba(56,189,248,0.15)' : 'transparent', color: difficulty === lvl ? '#38BDF8' : '#94A3B8', border: 'none', cursor: 'pointer', textAlign: 'left', fontWeight: 700, fontSize: '0.82rem' }}
                  >
                    {lvl}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Boutons upload fichier (style pill) */}
        <div style={{ display: 'flex', gap: 8, marginTop: 10, flexWrap: 'wrap' }}>
          <button onClick={() => fileInputRef.current?.click()} style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '7px 14px', borderRadius: 20, border: '1px solid rgba(56,189,248,0.3)', background: 'rgba(56,189,248,0.06)', color: '#38BDF8', cursor: 'pointer', fontSize: '0.78rem', fontWeight: 700 }}>
            <Upload size={14} /> PDF / Word / Excel
          </button>
          <button onClick={() => cameraInputRef.current?.click()} style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '7px 14px', borderRadius: 20, border: '1px solid rgba(168,85,247,0.3)', background: 'rgba(168,85,247,0.06)', color: '#A855F7', cursor: 'pointer', fontSize: '0.78rem', fontWeight: 700 }}>
            <Camera size={14} /> Photo épreuve
          </button>
        </div>
      </div>

      {/* ── Réponse ────────────────────────────────────────────────────────── */}
      {response && (
        <div className="ai-response" style={{ marginTop: 20 }}>
          {response.type === 'error' ? (
            <div style={{ padding: '14px 18px', borderRadius: 14, background: 'rgba(239,68,68,0.1)', border: '1px solid rgba(239,68,68,0.25)', color: '#FCA5A5', fontSize: '0.88rem' }}>
              {response.content}
            </div>
          ) : response.type === 'quiz' && response.questions?.length ? (
            /* Quiz structuré */
            <div>
              <h3 style={{ color: '#F1F5F9', fontSize: '1rem', fontWeight: 800, marginBottom: 14 }}>
                🎯 {response.titre}
              </h3>
              {response.questions.map((q, i) => (
                <div key={i} style={{ marginBottom: 18, padding: '14px 18px', borderRadius: 14, background: 'rgba(245,158,11,0.06)', border: '1px solid rgba(245,158,11,0.15)' }}>
                  <p style={{ color: '#F1F5F9', fontWeight: 700, marginBottom: 10, fontSize: '0.9rem' }}>
                    Q{i+1}. {q.question}
                  </p>
                  {(q.options || []).map((opt, j) => (
                    <p key={j} style={{ color: opt === q.reponse_correcte ? '#10B981' : '#94A3B8', margin: '4px 0', fontSize: '0.85rem', paddingLeft: 12, borderLeft: opt === q.reponse_correcte ? '3px solid #10B981' : '3px solid transparent' }}>
                      {opt} {opt === q.reponse_correcte ? '✓' : ''}
                    </p>
                  ))}
                  {q.explication && (
                    <p style={{ color: '#475569', fontSize: '0.78rem', marginTop: 8, fontStyle: 'italic' }}>
                      💡 {q.explication}
                    </p>
                  )}
                </div>
              ))}
            </div>
          ) : (
            /* Réponse texte standard */
            <div style={{ padding: '16px 20px', borderRadius: 14, background: 'rgba(56,189,248,0.06)', border: '1px solid rgba(56,189,248,0.15)' }}>
              {response.filename && (
                <p style={{ color: '#475569', fontSize: '0.75rem', marginBottom: 10 }}>
                  📄 {response.filename}
                </p>
              )}
              <p style={{ color: '#334155', fontSize: '0.88rem', lineHeight: 1.7, whiteSpace: 'pre-wrap', margin: 0 }}>
                {response.content}
              </p>
              {response.corrections && (
                <div style={{ marginTop: 14, paddingTop: 14, borderTop: '1px solid #f1f5f9' }}>
                  <p style={{ color: '#475569', fontSize: '0.8rem', fontWeight: 700, marginBottom: 6 }}>📌 Corrections</p>
                  <p style={{ color: '#334155', fontSize: '0.85rem', whiteSpace: 'pre-wrap' }}>{response.corrections}</p>
                </div>
              )}
              {response.grade && (
                <div style={{ marginTop: 10, display: 'inline-block', padding: '4px 12px', borderRadius: 20, background: 'rgba(16,185,129,0.15)', border: '1px solid rgba(16,185,129,0.3)', color: '#10B981', fontWeight: 800, fontSize: '0.82rem' }}>
                  Note estimée: {response.grade}
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Spinner CSS */}
      <style>{`@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}
