import React, { useState, useEffect } from 'react';
import { FileCheck, ChevronLeft, Loader } from 'lucide-react';
import { epreuveAPI } from '../services/api';
import SubmissionForm from './SubmissionForm';

/**
 * Liste des épreuves + formulaire de soumission pour correction prof.
 */
const MesSoumissionsPanel = ({ user }) => {
  const [epreuves, setEpreuves] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState(null);

  useEffect(() => {
    epreuveAPI.getAll()
      .then((r) => setEpreuves(r.data || []))
      .catch(() => setEpreuves([]))
      .finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div style={{ padding: '40px', textAlign: 'center', color: '#475569' }}>
        <Loader className="spinner" size={24} /> Chargement des épreuves…
      </div>
    );
  }

  if (selected) {
    return (
      <div style={{ padding: '16px' }}>
        <button
          type="button"
          onClick={() => setSelected(null)}
          style={{
            display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '16px',
            background: '#f1f5f9', border: '1px solid #e2e8f0',
            borderRadius: '10px', padding: '8px 14px', color: '#475569', cursor: 'pointer',
            fontWeight: 700, fontSize: '0.82rem',
          }}
        >
          <ChevronLeft size={16} /> Retour à la liste
        </button>
        <SubmissionForm
          epreuveId={selected.id}
          epreuveTitle={selected.titre}
          user={user}
          onSubmitted={() => setSelected(null)}
        />
      </div>
    );
  }

  return (
    <div style={{ padding: '16px' }}>
      <p style={{ color: '#475569', fontSize: '0.88rem', margin: '0 0 16px' }}>
        Choisissez une épreuve et envoyez votre copie pour correction par votre professeur ou l'IA.
      </p>
      {epreuves.length === 0 ? (
        <p style={{ color: '#475569', textAlign: 'center', padding: '24px' }}>
          Aucune épreuve disponible pour le moment.
        </p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {epreuves.slice(0, 30).map((ep) => (
            <button
              key={ep.id}
              type="button"
              onClick={() => setSelected(ep)}
              style={{
                textAlign: 'left', padding: '14px 16px', borderRadius: '12px',
                background: '#f8fafc', border: '1px solid #e2e8f0',
                cursor: 'pointer', color: '#0c1730',
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <FileCheck size={18} color="#38BDF8" />
                <div>
                  <div style={{ fontWeight: 700, fontSize: '0.92rem' }}>{ep.titre}</div>
                  <div style={{ color: '#475569', fontSize: '0.78rem', marginTop: '2px' }}>
                    {ep.matiere?.nom || 'Matière'} · {ep.matiere?.niveau || ep.niveau || '—'}
                  </div>
                </div>
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

export default MesSoumissionsPanel;
