import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Loader, Download, Sparkles, RotateCcw, CheckCircle2, Plus, Trash2, User, GraduationCap, ChevronRight, ChevronLeft, Palette, Layers, BookOpen } from 'lucide-react';
import { aiAPI, BACKEND_BASE_URL } from '../services/api';

/* ══════════════════════════════════════════════════════════
   THÈMES VISUELS — chaque thème affiche ses couleurs live
   ══════════════════════════════════════════════════════════ */
const THEMES = [
  {
    id: 'saphir',
    nom: 'Saphir',
    emoji: '💎',
    desc: 'Bleu professionnel',
    bg: '#0c1a3a',
    accent: '#0ea5e9',
    accent2: '#38bdf8',
    text: '#f0f9ff',
    muted: '#7dd3fc',
    gradient: 'linear-gradient(135deg, #0c1a3a 0%, #1e3a5f 50%, #0369a1 100%)',
    dots: ['#0c1a3a', '#0ea5e9', '#38bdf8'],
  },
  {
    id: 'harmattan',
    nom: 'Harmattan',
    emoji: '🌬️',
    desc: 'Chaleur saharienne',
    bg: '#1c0a02',
    accent: '#ea580c',
    accent2: '#fb923c',
    text: '#fff7ed',
    muted: '#fed7aa',
    gradient: 'linear-gradient(135deg, #1c0a02 0%, #7c2d12 50%, #c2410c 100%)',
    dots: ['#1c0a02', '#ea580c', '#fb923c'],
  },
  {
    id: 'moisson',
    nom: 'Moisson',
    emoji: '🌾',
    desc: 'Or des champs',
    bg: '#1a1500',
    accent: '#ca8a04',
    accent2: '#facc15',
    text: '#fefce8',
    muted: '#fde68a',
    gradient: 'linear-gradient(135deg, #1a1500 0%, #713f12 50%, #a16207 100%)',
    dots: ['#1a1500', '#ca8a04', '#facc15'],
  },
  {
    id: 'savane',
    nom: 'Savane',
    emoji: '🌿',
    desc: 'Nature africaine',
    bg: '#052e16',
    accent: '#16a34a',
    accent2: '#4ade80',
    text: '#f0fdf4',
    muted: '#86efac',
    gradient: 'linear-gradient(135deg, #052e16 0%, #14532d 50%, #15803d 100%)',
    dots: ['#052e16', '#16a34a', '#4ade80'],
  },
  {
    id: 'eclipse',
    nom: 'Éclipse',
    emoji: '🌙',
    desc: 'Élégance nocturne',
    bg: '#09090b',
    accent: '#a78bfa',
    accent2: '#c4b5fd',
    text: '#faf5ff',
    muted: '#ddd6fe',
    gradient: 'linear-gradient(135deg, #09090b 0%, #1e1b4b 50%, #4c1d95 100%)',
    dots: ['#09090b', '#a78bfa', '#c4b5fd'],
  },
  {
    id: 'corail',
    nom: 'Corail',
    emoji: '🪸',
    desc: 'Vivacité tropicale',
    bg: '#1a0a0a',
    accent: '#f43f5e',
    accent2: '#fb7185',
    text: '#fff1f2',
    muted: '#fecdd3',
    gradient: 'linear-gradient(135deg, #1a0a0a 0%, #881337 50%, #be123c 100%)',
    dots: ['#1a0a0a', '#f43f5e', '#fb7185'],
  },
];

const TITRES_PROF = ['Pr.', 'Dr.', 'Prof.', 'M.', 'Mme', 'Dr Ing.', 'Ing.'];

/* ══════════════════════════════════════════════════════════
   COMPOSANT PRINCIPAL
   ══════════════════════════════════════════════════════════ */
const GenererPowerPoint = ({ cours, onClose, onPointsConsumed }) => {
  /* ─── Étapes : 1=Infos, 2=Thème, 3=Résultat ─── */
  const [etape, setEtape] = useState(1);

  /* ─── Étape 1 : infos ─── */
  const [theme, setTheme] = useState(cours?.titre || '');
  const [nbSlides, setNbSlides] = useState(7);
  const [auteurs, setAuteurs] = useState(['']);
  const [titreProf, setTitreProf] = useState('Pr.');
  const [nomProf, setNomProf] = useState('');
  const [institution, setInstitution] = useState('');

  /* ─── Étape 2 : thème visuel ─── */
  const [themeVisuel, setThemeVisuel] = useState(THEMES[0]);

  /* ─── Étape 3 : génération ─── */
  const [loading, setLoading] = useState(false);
  const [erreur, setErreur] = useState('');
  const [presentation, setPresentation] = useState(null);
  const [exportOk, setExportOk] = useState(false);

  /* ─── Gestion auteurs ─── */
  const ajouterAuteur = () => setAuteurs(a => [...a, '']);
  const retirerAuteur = (i) => setAuteurs(a => a.filter((_, idx) => idx !== i));
  const majAuteur = (i, v) => setAuteurs(a => a.map((x, idx) => idx === i ? v : x));

  /* ─── Extraction JSON robuste ─── */
  const extraireJSON = (txt) => {
    if (!txt) return null;
    let clean = String(txt).replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
    const m = clean.match(/\{[\s\S]*\}/);
    if (!m) return null;
    try { return JSON.parse(m[0]); } catch { return null; }
  };

  /* ─── Génération IA ─── */
  const generer = async () => {
    if (!theme.trim()) { setErreur('Entrez un thème.'); return; }
    setErreur(''); setLoading(true); setPresentation(null); setExportOk(false);
    try {
      const auteursListe = auteurs.filter(a => a.trim()).join(', ');
      const encadreur = nomProf.trim() ? `${titreProf} ${nomProf.trim()}` : '';
      const hasFile = !!(cours?.fichierLocal || cours?.fichierUrl);

      const prompt =
        `Crée une présentation PowerPoint professionnelle sur : "${theme}".\n` +
        `Auteurs : ${auteursListe || 'Non précisé'}. ${encadreur ? `Encadreur : ${encadreur}.` : ''}\n` +
        `${institution ? `Institution : ${institution}.` : ''}\n` +
        `Génère exactement ${nbSlides} slides de contenu. ` +
        (hasFile
          ? `IMPORTANT : lis attentivement le document de cours joint et base les slides EXCLUSIVEMENT sur son contenu réel (chapitres, définitions, théorèmes, exemples).\n`
          : `\n`) +
        `Réponds UNIQUEMENT en JSON strict :\n` +
        `{"titre":"Titre principal","slides":[{"titre":"Titre slide","points":["point 1","point 2","point 3"]}]}\n` +
        `Chaque slide : titre clair + 3 à 5 points concis et informatifs.`;

      let res;
      if (cours?.fichierLocal) {
        // Fichier Blob local (cours non encore synchronisé ou récemment importé)
        const fd = new FormData();
        fd.append('question', prompt);
        fd.append('file', cours.fichierLocal, cours.fichierLocalName || cours.titre || 'cours');
        res = await aiAPI.chat(fd);
      } else if (cours?.fichierUrl) {
        // Cours synchronisé : télécharger le fichier puis l'envoyer
        const url = cours.fichierUrl.startsWith('http')
          ? cours.fichierUrl
          : `${BACKEND_BASE_URL}${cours.fichierUrl.startsWith('/') ? cours.fichierUrl : '/' + cours.fichierUrl}`;
        try {
          const fetchRes = await fetch(url);
          if (fetchRes.ok) {
            const blob = await fetchRes.blob();
            const fd = new FormData();
            fd.append('question', prompt);
            fd.append('file', blob, cours.titre || 'cours');
            res = await aiAPI.chat(fd);
          } else throw new Error('fetch failed');
        } catch {
          // Fallback : passer l'URL si le téléchargement échoue
          res = await aiAPI.ask(prompt, 'Étudiant', null, url);
        }
      } else {
        // Aucun cours → génération libre sur le thème saisi
        res = await aiAPI.ask(prompt, 'Étudiant', null, null);
      }

      const answer = res.data?.answer || res.data?.text || '';
      const data = extraireJSON(answer);
      if (!data || !Array.isArray(data.slides) || data.slides.length === 0) {
        setErreur("L'IA n'a pas pu structurer la présentation. Réessaie ou reformule.");
      } else {
        setPresentation(data);
        if (onPointsConsumed) onPointsConsumed();
        setEtape(3);
      }
    } catch (e) {
      setErreur(e?.response?.data?.error || 'Erreur réseau. Réessaie.');
    } finally { setLoading(false); }
  };

  /* ─── Chargement pptxgenjs ─── */
  const chargerPptxLib = () => new Promise((resolve, reject) => {
    if (window.PptxGenJS) return resolve(window.PptxGenJS);
    const s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/pptxgenjs@3.12.0/dist/pptxgen.bundle.js';
    s.onload = () => resolve(window.PptxGenJS);
    s.onerror = () => reject(new Error('Chargement impossible'));
    document.head.appendChild(s);
  });

  /* ─── Téléchargement PPTX ─── */
  const telechargerPptx = async () => {
    if (!presentation) return;
    try {
      const PptxGenJS = await chargerPptxLib();
      const pptx = new PptxGenJS();
      const tv = themeVisuel;

      const auteursListe = auteurs.filter(a => a.trim());
      const encadreur = nomProf.trim() ? `${titreProf} ${nomProf.trim()}` : '';

      pptx.author = auteursListe.join(', ') || 'RevisIA_H24';
      pptx.title = presentation.titre || theme;
      pptx.layout = 'LAYOUT_WIDE';

      // ── SLIDE DE COUVERTURE ──
      const cover = pptx.addSlide();
      cover.background = { fill: tv.bg.replace('#', '') };

      // Bandeau accent en haut
      cover.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: '100%', h: 0.08, fill: { color: tv.accent.replace('#', '') } });

      // Titre principal
      cover.addText(presentation.titre || theme, {
        x: 0.6, y: 1.0, w: 11.8, h: 1.6,
        fontSize: 40, bold: true, color: tv.accent.replace('#', ''),
        align: 'center', breakLine: false
      });

      // Ligne décorative
      cover.addShape(pptx.ShapeType.rect, { x: 3.5, y: 2.8, w: 6, h: 0.04, fill: { color: tv.accent2.replace('#', '') } });

      // Sous-titre (institution)
      if (institution) {
        cover.addText(institution, {
          x: 0.6, y: 3.0, w: 11.8, h: 0.5,
          fontSize: 14, color: tv.muted.replace('#', ''),
          align: 'center', italic: true
        });
      }

      // Auteurs
      if (auteursListe.length > 0) {
        const auteursText = auteursListe.length === 1
          ? `Présenté par : ${auteursListe[0]}`
          : `Présenté par : ${auteursListe.join(' — ')}`;
        cover.addText(auteursText, {
          x: 0.6, y: 3.7, w: 11.8, h: 0.6,
          fontSize: 16, color: tv.text.replace('#', ''),
          align: 'center', bold: true
        });
      }

      // Encadreur
      if (encadreur) {
        cover.addText(`Sous la direction de : ${encadreur}`, {
          x: 0.6, y: 4.35, w: 11.8, h: 0.5,
          fontSize: 13, color: tv.muted.replace('#', ''),
          align: 'center'
        });
      }

      // Date
      const dateStr = new Date().toLocaleDateString('fr-FR', { year: 'numeric', month: 'long' });
      cover.addText(dateStr, {
        x: 0.6, y: 5.1, w: 11.8, h: 0.4,
        fontSize: 12, color: tv.muted.replace('#', ''),
        align: 'center'
      });

      // Bandeau bas
      cover.addShape(pptx.ShapeType.rect, { x: 0, y: 6.85, w: '100%', h: 0.65, fill: { color: tv.accent.replace('#', '') + '33' } });
      cover.addText('Généré avec RevisIA_H24 — IA pour l\'éducation africaine', {
        x: 0.6, y: 6.88, w: 11.8, h: 0.55,
        fontSize: 10, color: tv.muted.replace('#', ''),
        align: 'center'
      });

      // ── SLIDES DE CONTENU ──
      presentation.slides.forEach((s, idx) => {
        const slide = pptx.addSlide();
        slide.background = { fill: tv.bg.replace('#', '') };

        // Bandeau titre
        slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: '100%', h: 1.2, fill: { color: tv.accent.replace('#', '') + '22' } });
        slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: 0.06, h: 1.2, fill: { color: tv.accent.replace('#', '') } });

        // Titre slide
        slide.addText(s.titre || `Section ${idx + 1}`, {
          x: 0.3, y: 0.1, w: 11.4, h: 1.0,
          fontSize: 26, bold: true, color: tv.accent.replace('#', ''),
          valign: 'middle'
        });

        // Points
        const bullets = (s.points || []).map(p => ({
          text: String(p),
          options: {
            bullet: { type: 'bullet', code: '25B8', color: tv.accent2.replace('#', '') },
            color: tv.text.replace('#', ''),
            fontSize: 18,
            paraSpaceAfter: 12,
            indentLevel: 0
          }
        }));
        if (bullets.length) {
          slide.addText(bullets, { x: 0.5, y: 1.45, w: 11.5, h: 4.8, valign: 'top' });
        }

        // Pied de page
        slide.addShape(pptx.ShapeType.rect, { x: 0, y: 7.0, w: '100%', h: 0.5, fill: { color: tv.accent.replace('#', '') + '18' } });
        slide.addText(`${presentation.titre || theme}  •  ${idx + 1} / ${presentation.slides.length}`, {
          x: 0.4, y: 7.05, w: 8, h: 0.38,
          fontSize: 10, color: tv.muted.replace('#', ''),
        });
        if (auteursListe.length > 0) {
          slide.addText(auteursListe[0], {
            x: 9, y: 7.05, w: 3.4, h: 0.38,
            fontSize: 10, color: tv.muted.replace('#', ''),
            align: 'right'
          });
        }
      });

      // ── SLIDE CONCLUSION ──
      const fin = pptx.addSlide();
      fin.background = { fill: tv.bg.replace('#', '') };
      fin.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: '100%', h: 0.08, fill: { color: tv.accent.replace('#', '') } });
      fin.addText('Merci pour votre attention', {
        x: 0.6, y: 2.3, w: 11.8, h: 1.2,
        fontSize: 38, bold: true, color: tv.accent.replace('#', ''),
        align: 'center'
      });
      fin.addShape(pptx.ShapeType.rect, { x: 3.5, y: 3.7, w: 6, h: 0.04, fill: { color: tv.accent2.replace('#', '') } });
      if (encadreur) {
        fin.addText(`Encadreur : ${encadreur}`, {
          x: 0.6, y: 4.2, w: 11.8, h: 0.5,
          fontSize: 14, color: tv.muted.replace('#', ''),
          align: 'center', italic: true
        });
      }
      fin.addText(auteursListe.join(' — ') || '', {
        x: 0.6, y: 4.85, w: 11.8, h: 0.5,
        fontSize: 16, bold: true, color: tv.text.replace('#', ''),
        align: 'center'
      });

      const nom = (presentation.titre || theme).replace(/[^a-z0-9]+/gi, '_').slice(0, 40);
      await pptx.writeFile({ fileName: `${nom || 'presentation'}_RevisIA.pptx` });
      setExportOk(true);
    } catch (e) {
      console.error(e);
      setErreur('Erreur lors de la création du fichier PowerPoint.');
    }
  };

  /* ════════════════════════════════════════
     RENDU
     ════════════════════════════════════════ */
  return (
    <motion.div
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.45)', backdropFilter: 'blur(8px)', zIndex: 9500, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
    >
      <motion.div
        initial={{ scale: 0.94, y: 24, opacity: 0 }} animate={{ scale: 1, y: 0, opacity: 1 }} transition={{ type: 'spring', damping: 22, stiffness: 300 }}
        style={{ background: '#fff', border: '1px solid #e2e8f0', borderRadius: 24, width: '100%', maxWidth: 620, maxHeight: '92vh', overflowY: 'auto', boxShadow: '0 24px 64px rgba(0,0,0,0.12)' }}
      >
        {/* ── EN-TÊTE ── */}
        <div style={{ padding: '22px 24px 0', display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', borderBottom: '1px solid #f1f5f9', paddingBottom: 18 }}>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <div style={{ background: 'linear-gradient(135deg, #f97316, #ea580c)', borderRadius: 10, width: 38, height: 38, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Layers size={19} color="#fff" />
              </div>
              <div>
                <h2 style={{ color: '#0f172a', fontWeight: 900, fontSize: '1.15rem', margin: 0 }}>Créer une Présentation</h2>
                <p style={{ color: '#64748b', fontSize: '0.78rem', margin: 0 }}>PowerPoint professionnel généré par IA</p>
              </div>
            </div>
            {/* Indicateur d'étapes */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 14 }}>
              {[
                { n: 1, label: 'Informations' },
                { n: 2, label: 'Thème visuel' },
                { n: 3, label: 'Résultat' },
              ].map(({ n, label }) => (
                <React.Fragment key={n}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                    <div style={{
                      width: 26, height: 26, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center',
                      fontSize: '0.75rem', fontWeight: 800,
                      background: etape === n ? '#0369a1' : etape > n ? '#16a34a' : '#e2e8f0',
                      color: etape >= n ? '#fff' : '#94a3b8',
                      transition: 'all 0.3s'
                    }}>{etape > n ? '✓' : n}</div>
                    <span style={{ fontSize: '0.72rem', fontWeight: 600, color: etape === n ? '#0369a1' : etape > n ? '#16a34a' : '#94a3b8' }}>{label}</span>
                  </div>
                  {n < 3 && <div style={{ flex: 1, height: 2, background: etape > n ? '#16a34a' : '#e2e8f0', borderRadius: 2, maxWidth: 32, transition: 'background 0.3s' }} />}
                </React.Fragment>
              ))}
            </div>
          </div>
          <button onClick={onClose} style={{ background: '#f1f5f9', border: 'none', borderRadius: 10, width: 36, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: '#64748b', flexShrink: 0 }}>
            <X size={17} />
          </button>
        </div>

        <div style={{ padding: '22px 24px 28px' }}>
          <AnimatePresence mode="wait">

            {/* ══════════════════════════════
                ÉTAPE 1 — INFORMATIONS
                ══════════════════════════════ */}
            {etape === 1 && (
              <motion.div key="etape1" initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 20 }} transition={{ duration: 0.22 }}>

                {/* Bannière cours — affiché uniquement si un cours est fourni */}
                {cours ? (
                  <div style={{ background: 'linear-gradient(135deg, #f0f9ff, #e0f2fe)', border: '1px solid #bae6fd', borderRadius: 12, padding: '10px 14px', marginBottom: 18, display: 'flex', alignItems: 'center', gap: 10 }}>
                    <BookOpen size={16} color="#0369a1" />
                    <div>
                      <div style={{ color: '#0369a1', fontWeight: 800, fontSize: '0.74rem', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Basé sur votre cours</div>
                      <div style={{ color: '#0c4a6e', fontSize: '0.87rem', fontWeight: 700, marginTop: 2 }}>{cours.titre}</div>
                    </div>
                  </div>
                ) : (
                  <div style={{ background: '#fafafa', border: '1px dashed #e2e8f0', borderRadius: 12, padding: '10px 14px', marginBottom: 18, display: 'flex', alignItems: 'center', gap: 10 }}>
                    <Sparkles size={15} color="#94a3b8" />
                    <div style={{ color: '#94a3b8', fontSize: '0.8rem' }}>Génération libre — aucun cours sélectionné. Pour une présentation plus précise, utilisez le bouton <strong>📊 PPT</strong> sur une carte de cours.</div>
                  </div>
                )}

                {/* Thème */}
                <div style={fieldWrapper}>
                  <label style={labelStyle}><Sparkles size={12} style={{ marginRight: 4 }} />Thème / Sujet de la présentation</label>
                  <input
                    type="text" value={theme} onChange={e => { setErreur(''); setTheme(e.target.value); }}
                    placeholder="Ex: Les changements climatiques en Afrique, La photosynthèse…"
                    style={inputStyle}
                  />
                </div>

                {/* Noms des auteurs */}
                <div style={fieldWrapper}>
                  <label style={labelStyle}><User size={12} style={{ marginRight: 4 }} />Auteur(s) — Noms des présentateurs</label>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                    {auteurs.map((a, i) => (
                      <div key={i} style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                        <input
                          type="text" value={a} onChange={e => majAuteur(i, e.target.value)}
                          placeholder={i === 0 ? 'Votre nom complet' : `Auteur ${i + 1}`}
                          style={{ ...inputStyle, flex: 1, marginBottom: 0 }}
                        />
                        {auteurs.length > 1 && (
                          <button onClick={() => retirerAuteur(i)} style={{ background: '#fef2f2', border: '1px solid #fecaca', borderRadius: 8, width: 34, height: 34, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: '#ef4444', flexShrink: 0 }}>
                            <Trash2 size={14} />
                          </button>
                        )}
                      </div>
                    ))}
                    {auteurs.length < 6 && (
                      <button onClick={ajouterAuteur} style={{ display: 'flex', alignItems: 'center', gap: 6, background: '#f0f9ff', border: '1.5px dashed #bae6fd', borderRadius: 10, padding: '8px 14px', cursor: 'pointer', color: '#0369a1', fontSize: '0.8rem', fontWeight: 700 }}>
                        <Plus size={14} /> Ajouter un auteur
                      </button>
                    )}
                  </div>
                </div>

                {/* Professeur */}
                <div style={fieldWrapper}>
                  <label style={labelStyle}><GraduationCap size={12} style={{ marginRight: 4 }} />Encadreur / Professeur (optionnel)</label>
                  <div style={{ display: 'flex', gap: 8 }}>
                    <select
                      value={titreProf} onChange={e => setTitreProf(e.target.value)}
                      style={{ ...inputStyle, flex: '0 0 auto', width: 110, marginBottom: 0 }}
                    >
                      {TITRES_PROF.map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                    <input
                      type="text" value={nomProf} onChange={e => setNomProf(e.target.value)}
                      placeholder="Nom du professeur"
                      style={{ ...inputStyle, flex: 1, marginBottom: 0 }}
                    />
                  </div>
                </div>

                {/* Institution */}
                <div style={fieldWrapper}>
                  <label style={labelStyle}>Institution (optionnel)</label>
                  <input
                    type="text" value={institution} onChange={e => setInstitution(e.target.value)}
                    placeholder="Ex: Université de Lomé, Faculté des Sciences…"
                    style={inputStyle}
                  />
                </div>

                {/* Nombre de slides */}
                <div style={fieldWrapper}>
                  <label style={labelStyle}>Nombre de slides de contenu : <strong style={{ color: '#0369a1' }}>{nbSlides}</strong></label>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                    <span style={{ color: '#94a3b8', fontSize: '0.75rem', fontWeight: 700 }}>3</span>
                    <input type="range" min="3" max="12" value={nbSlides} onChange={e => setNbSlides(Number(e.target.value))}
                      style={{ flex: 1, accentColor: '#0369a1', height: 4 }} />
                    <span style={{ color: '#94a3b8', fontSize: '0.75rem', fontWeight: 700 }}>12</span>
                  </div>
                  <p style={{ color: '#94a3b8', fontSize: '0.72rem', marginTop: 4 }}>
                    Total : {nbSlides + 2} slides (couverture + {nbSlides} contenu + conclusion)
                  </p>
                </div>

                {erreur && <p style={{ color: '#ef4444', fontSize: '0.83rem', marginBottom: 12, background: '#fef2f2', padding: '8px 12px', borderRadius: 8 }}>{erreur}</p>}

                <button
                  onClick={() => { if (!theme.trim()) { setErreur('Le thème est obligatoire.'); return; } setErreur(''); setEtape(2); }}
                  style={{ ...btnPrimary, width: '100%' }}
                >
                  Choisir le thème visuel <ChevronRight size={16} />
                </button>
              </motion.div>
            )}

            {/* ══════════════════════════════
                ÉTAPE 2 — THÈME VISUEL
                ══════════════════════════════ */}
            {etape === 2 && (
              <motion.div key="etape2" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} transition={{ duration: 0.22 }}>

                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16 }}>
                  <Palette size={16} color="#0369a1" />
                  <h3 style={{ margin: 0, fontSize: '0.95rem', fontWeight: 800, color: '#0f172a' }}>Choisissez votre thème visuel</h3>
                </div>
                <p style={{ color: '#64748b', fontSize: '0.8rem', marginBottom: 18, marginTop: -8 }}>Les couleurs seront appliquées sur toutes vos slides.</p>

                {/* Grille thèmes — chaque carte EST son thème */}
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 10, marginBottom: 20 }}>
                  {THEMES.map(t => (
                    <button
                      key={t.id}
                      onClick={() => setThemeVisuel(t)}
                      style={{
                        background: t.gradient,
                        border: themeVisuel.id === t.id ? `3px solid #fff` : '3px solid transparent',
                        outline: themeVisuel.id === t.id ? `2px solid ${t.accent}` : '2px solid transparent',
                        borderRadius: 14,
                        overflow: 'hidden',
                        cursor: 'pointer',
                        padding: '14px 12px',
                        transition: 'all 0.22s cubic-bezier(0.34,1.56,0.64,1)',
                        boxShadow: themeVisuel.id === t.id
                          ? `0 6px 24px ${t.accent}55`
                          : '0 2px 10px rgba(0,0,0,0.25)',
                        transform: themeVisuel.id === t.id ? 'scale(1.04)' : 'scale(1)',
                        textAlign: 'left',
                        position: 'relative',
                      }}
                    >
                      {/* Badge sélectionné */}
                      {themeVisuel.id === t.id && (
                        <div style={{ position: 'absolute', top: 8, right: 8, background: '#fff', borderRadius: '50%', width: 22, height: 22, display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 2px 8px rgba(0,0,0,0.3)' }}>
                          <CheckCircle2 size={14} color={t.accent} />
                        </div>
                      )}

                      {/* Emoji + Nom (sur fond coloré = toujours visible) */}
                      <div style={{ fontSize: '1.6rem', marginBottom: 6, lineHeight: 1 }}>{t.emoji}</div>
                      <div style={{ color: t.accent, fontWeight: 900, fontSize: '0.88rem', marginBottom: 2 }}>{t.nom}</div>
                      <div style={{ color: t.muted, fontSize: '0.68rem', marginBottom: 10, opacity: 0.9 }}>{t.desc}</div>

                      {/* Mini simulation d'une diapo */}
                      <div style={{ background: 'rgba(255,255,255,0.1)', borderRadius: 6, padding: '7px 8px', border: `1px solid ${t.accent}40` }}>
                        <div style={{ background: t.accent, height: 3, borderRadius: 2, width: '65%', marginBottom: 5 }} />
                        <div style={{ background: t.text, height: 2, borderRadius: 2, width: '90%', marginBottom: 3, opacity: 0.6 }} />
                        <div style={{ background: t.text, height: 2, borderRadius: 2, width: '75%', marginBottom: 3, opacity: 0.4 }} />
                        <div style={{ background: t.text, height: 2, borderRadius: 2, width: '55%', opacity: 0.4 }} />
                      </div>

                      {/* Points de couleur */}
                      <div style={{ display: 'flex', gap: 5, marginTop: 8 }}>
                        {t.dots.map((d, i) => (
                          <div key={i} style={{ width: 9, height: 9, borderRadius: '50%', background: d, border: '1.5px solid rgba(255,255,255,0.45)', boxShadow: '0 1px 3px rgba(0,0,0,0.3)' }} />
                        ))}
                      </div>
                    </button>
                  ))}
                </div>

                {/* Aperçu de la diapo de couverture — sur fond coloré */}
                <div style={{ marginBottom: 20 }}>
                  <p style={{ fontSize: '0.76rem', fontWeight: 800, color: '#334155', marginBottom: 10, textTransform: 'uppercase', letterSpacing: '0.5px' }}>
                    Aperçu de ta diapo de couverture
                  </p>
                  <motion.div
                    key={themeVisuel.id}
                    initial={{ opacity: 0.6, scale: 0.98 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ duration: 0.25 }}
                    style={{ background: themeVisuel.gradient, borderRadius: 14, padding: '22px 24px', boxShadow: `0 8px 28px ${themeVisuel.accent}30`, minHeight: 130, display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}
                  >
                    {/* Barre d'accent en haut */}
                    <div style={{ height: 4, background: themeVisuel.accent, borderRadius: 2, width: '100%', marginBottom: 14 }} />

                    {/* Titre */}
                    <div style={{ color: themeVisuel.accent, fontWeight: 900, fontSize: '1.1rem', lineHeight: 1.3, marginBottom: 10 }}>
                      {theme || '— Titre de la présentation —'}
                    </div>

                    {/* Auteurs */}
                    <div style={{ color: themeVisuel.text, fontSize: '0.8rem', fontWeight: 700, marginBottom: 4, opacity: 0.95 }}>
                      {auteurs.filter(a => a.trim()).length > 0
                        ? `✍️ ${auteurs.filter(a => a.trim()).join(' · ')}`
                        : '✍️ Auteur(s) — à saisir à l\'étape 1'}
                    </div>

                    {/* Encadreur */}
                    {nomProf.trim() && (
                      <div style={{ color: themeVisuel.muted, fontSize: '0.74rem', marginBottom: 8, opacity: 0.9 }}>
                        Sous la direction de {titreProf} {nomProf}
                      </div>
                    )}
                    {institution && (
                      <div style={{ color: themeVisuel.muted, fontSize: '0.72rem', opacity: 0.8, fontStyle: 'italic' }}>
                        {institution}
                      </div>
                    )}

                    {/* Palette */}
                    <div style={{ display: 'flex', gap: 6, marginTop: 12 }}>
                      {themeVisuel.dots.map((d, i) => (
                        <div key={i} style={{ width: 10, height: 10, borderRadius: '50%', background: d, border: '1.5px solid rgba(255,255,255,0.4)', boxShadow: '0 1px 4px rgba(0,0,0,0.3)' }} />
                      ))}
                      <span style={{ color: themeVisuel.muted, fontSize: '0.66rem', marginLeft: 4, alignSelf: 'center', opacity: 0.8 }}>
                        {themeVisuel.emoji} Thème {themeVisuel.nom}
                      </span>
                    </div>
                  </motion.div>
                </div>

                {erreur && <p style={{ color: '#ef4444', fontSize: '0.83rem', marginBottom: 12, background: '#fef2f2', padding: '8px 12px', borderRadius: 8 }}>{erreur}</p>}

                <div style={{ display: 'flex', gap: 10 }}>
                  <button onClick={() => setEtape(1)} style={btnSecondary}>
                    <ChevronLeft size={16} /> Retour
                  </button>
                  <button onClick={generer} disabled={loading} style={{ ...btnPrimary, flex: 1, background: 'linear-gradient(135deg, #0369a1, #0ea5e9)' }}>
                    {loading
                      ? <><Loader size={16} style={{ animation: 'spin 1s linear infinite' }} /> Génération en cours…</>
                      : <><Sparkles size={16} /> Générer la présentation</>
                    }
                  </button>
                </div>
              </motion.div>
            )}

            {/* ══════════════════════════════
                ÉTAPE 3 — RÉSULTAT
                ══════════════════════════════ */}
            {etape === 3 && presentation && (
              <motion.div key="etape3" initial={{ opacity: 0, scale: 0.97 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: 0.25 }}>

                {/* Badge succès */}
                <div style={{ background: 'linear-gradient(135deg, #f0fdf4, #dcfce7)', border: '1px solid #86efac', borderRadius: 14, padding: '14px 18px', marginBottom: 18, display: 'flex', alignItems: 'center', gap: 12 }}>
                  <CheckCircle2 size={22} color="#16a34a" />
                  <div>
                    <div style={{ color: '#15803d', fontWeight: 800, fontSize: '0.95rem' }}>Présentation prête !</div>
                    <div style={{ color: '#4ade80', fontSize: '0.78rem' }}>
                      {presentation.slides.length} slides + couverture + conclusion — thème {themeVisuel.emoji} {themeVisuel.nom}
                    </div>
                  </div>
                </div>

                {/* Récapitulatif auteurs */}
                {(auteurs.filter(a => a.trim()).length > 0 || nomProf.trim()) && (
                  <div style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: 12, padding: '12px 16px', marginBottom: 16, display: 'flex', gap: 16, flexWrap: 'wrap' }}>
                    {auteurs.filter(a => a.trim()).length > 0 && (
                      <div>
                        <div style={{ fontSize: '0.7rem', color: '#94a3b8', fontWeight: 700, textTransform: 'uppercase', marginBottom: 3 }}>Auteurs</div>
                        <div style={{ fontSize: '0.85rem', fontWeight: 700, color: '#0f172a' }}>{auteurs.filter(a => a.trim()).join(', ')}</div>
                      </div>
                    )}
                    {nomProf.trim() && (
                      <div>
                        <div style={{ fontSize: '0.7rem', color: '#94a3b8', fontWeight: 700, textTransform: 'uppercase', marginBottom: 3 }}>Encadreur</div>
                        <div style={{ fontSize: '0.85rem', fontWeight: 700, color: '#0f172a' }}>{titreProf} {nomProf}</div>
                      </div>
                    )}
                  </div>
                )}

                {/* Aperçu slides */}
                <div style={{ maxHeight: 280, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 18, paddingRight: 4 }}>
                  {/* Slide couverture (mini) */}
                  <div style={{ background: themeVisuel.gradient, borderRadius: 10, padding: '10px 14px', boxShadow: `0 3px 12px ${themeVisuel.accent}30` }}>
                    <div style={{ color: themeVisuel.accent, fontWeight: 800, fontSize: '0.82rem' }}>🎯 COUVERTURE</div>
                    <div style={{ color: themeVisuel.text, fontSize: '0.78rem', marginTop: 2 }}>{presentation.titre}</div>
                  </div>
                  {presentation.slides.map((s, i) => (
                    <div key={i} style={{ padding: '10px 14px', borderRadius: 10, background: '#f8fafc', border: '1px solid #e2e8f0' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 5 }}>
                        <span style={{ background: themeVisuel.accent, color: '#fff', width: 20, height: 20, borderRadius: '50%', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.65rem', fontWeight: 800, flexShrink: 0 }}>{i + 1}</span>
                        <span style={{ color: '#0f172a', fontWeight: 700, fontSize: '0.85rem' }}>{s.titre}</span>
                      </div>
                      <ul style={{ margin: 0, paddingLeft: 28, color: '#475569', fontSize: '0.76rem', lineHeight: 1.7 }}>
                        {(s.points || []).slice(0, 3).map((p, j) => <li key={j}>{p}</li>)}
                        {(s.points || []).length > 3 && <li style={{ color: '#94a3b8' }}>+{s.points.length - 3} points…</li>}
                      </ul>
                    </div>
                  ))}
                  <div style={{ background: themeVisuel.gradient, borderRadius: 10, padding: '10px 14px', boxShadow: `0 3px 12px ${themeVisuel.accent}30` }}>
                    <div style={{ color: themeVisuel.accent, fontWeight: 800, fontSize: '0.82rem' }}>🏁 CONCLUSION</div>
                    <div style={{ color: themeVisuel.text, fontSize: '0.78rem', marginTop: 2 }}>Merci pour votre attention</div>
                  </div>
                </div>

                {erreur && <p style={{ color: '#ef4444', fontSize: '0.83rem', marginBottom: 12, background: '#fef2f2', padding: '8px 12px', borderRadius: 8 }}>{erreur}</p>}

                <div style={{ display: 'flex', gap: 10 }}>
                  <button onClick={() => { setPresentation(null); setExportOk(false); setEtape(1); }} style={btnSecondary}>
                    <RotateCcw size={15} /> Recommencer
                  </button>
                  <button onClick={telechargerPptx} style={{ ...btnPrimary, flex: 1, background: exportOk ? 'linear-gradient(135deg, #16a34a, #4ade80)' : 'linear-gradient(135deg, #f97316, #ea580c)' }}>
                    {exportOk
                      ? <><CheckCircle2 size={16} /> Téléchargé avec succès !</>
                      : <><Download size={16} /> Télécharger le .pptx</>
                    }
                  </button>
                </div>
              </motion.div>
            )}

          </AnimatePresence>
        </div>
      </motion.div>
    </motion.div>
  );
};

/* ══════════════════════════════════════════════════════════
   STYLES RÉUTILISABLES
   ══════════════════════════════════════════════════════════ */
const fieldWrapper = { marginBottom: 18 };

const labelStyle = {
  display: 'flex', alignItems: 'center',
  fontSize: '0.76rem', color: '#334155', fontWeight: 800,
  marginBottom: 8, textTransform: 'uppercase', letterSpacing: '0.5px'
};

const inputStyle = {
  width: '100%', padding: '11px 14px', borderRadius: 10,
  border: '1.5px solid #e2e8f0', background: '#f8fafc',
  color: '#0f172a', fontSize: '0.9rem', outline: 'none',
  boxSizing: 'border-box', fontFamily: 'inherit', marginBottom: 0,
  transition: 'border-color 0.2s',
};

const btnPrimary = {
  display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
  padding: '13px 20px', borderRadius: 12, border: 'none',
  cursor: 'pointer', fontWeight: 800, fontSize: '0.9rem',
  background: 'linear-gradient(135deg, #0369a1, #0ea5e9)',
  color: '#fff', transition: 'all 0.2s', letterSpacing: '0.01em',
};

const btnSecondary = {
  display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
  padding: '13px 16px', borderRadius: 12,
  border: '1.5px solid #e2e8f0', background: '#f8fafc',
  color: '#334155', cursor: 'pointer', fontWeight: 700, fontSize: '0.85rem',
  flexShrink: 0, transition: 'all 0.2s',
};

export default GenererPowerPoint;
