import React, { useState, useEffect } from 'react';
import { CheckCircle, AlertCircle, Star, Loader } from 'lucide-react';
import { courseworkAPI } from '../services/api';

/**
 * CourseworkReceived - Affiche les devoirs reçus par l'étudiant
 */
const CourseworkReceived = ({ user }) => {
  const [courseworks, setCourseworks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all'); // all, completed, pending
  const [completing, setCompleting] = useState(null);

  useEffect(() => {
    loadCourseworks();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]);

  const loadCourseworks = async () => {
    try {
      setLoading(true);
      const res = await courseworkAPI.getMesCourseworks(user.id);
      setCourseworks(res.data || []);
    } catch (err) {
      // Erreur silencieuse — afficher liste vide sans message d'erreur
      setCourseworks([]);
    } finally {
      setLoading(false);
    }
  };

  const handleMarkCompleted = async (courseworkId) => {
    try {
      setCompleting(courseworkId);
      await courseworkAPI.markAsCompleted(courseworkId);

      // Mettre à jour l'état local
      setCourseworks(courseworks.map(cw =>
        cw.id === courseworkId ? { ...cw, isCompleted: true } : cw
      ));
    } catch (err) {
      // Erreur silencieuse — l'état local n'est pas mis à jour
    } finally {
      setCompleting(null);
    }
  };

  // Filtrer les courseworks
  const filtered = courseworks.filter(cw => {
    if (filter === 'completed') return cw.isCompleted;
    if (filter === 'pending') return !cw.isCompleted;
    return true;
  });

  if (loading) return null; // Chargement silencieux

  return (
    <div className="coursework-panel">
      <div className="panel-header">
        <h3>📚 Mes Devoirs</h3>
        <p className="text-muted">Devoirs envoyés par vos professeurs</p>
      </div>

      {/* Filtres */}
      <div className="filter-tabs" style={{ marginBottom: '20px' }}>
        <button
          className={`filter-tab ${filter === 'all' ? 'active' : ''}`}
          onClick={() => setFilter('all')}
        >
          Tous ({courseworks.length})
        </button>
        <button
          className={`filter-tab ${filter === 'pending' ? 'active' : ''}`}
          onClick={() => setFilter('pending')}
        >
          À faire ({courseworks.filter(c => !c.isCompleted).length})
        </button>
        <button
          className={`filter-tab ${filter === 'completed' ? 'active' : ''}`}
          onClick={() => setFilter('completed')}
        >
          Complétés ✅ ({courseworks.filter(c => c.isCompleted).length})
        </button>
      </div>

      {/* Liste Courseworks */}
      <div className="coursework-list">
        {filtered.length === 0 ? (
          <div className="empty-state">
            <h4>📚 Pas de devoirs</h4>
            <p>
              {filter === 'completed' ? 'Aucun devoir complété' : 'Vérifiez plus tard pour de nouveaux devoirs!'}
            </p>
          </div>
        ) : (
          filtered.map(cw => (
            <div key={cw.id} className={`coursework-item ${cw.isCompleted ? 'completed' : ''}`}>
              <div className="coursework-title-row">
                <div className="coursework-title">
                  {cw.isCompleted ? (
                    <CheckCircle size={20} className="check-icon" />
                  ) : (
                    <AlertCircle size={20} className="alert-icon" />
                  )}
                  <span>{cw.titre}</span>
                </div>
                <span className="difficulty-badge">
                  {[...Array(cw.niveau_difficulte)].map((_, i) => (
                    <Star key={i} size={14} fill="currentColor" />
                  ))}
                </span>
              </div>

              {cw.description && (
                <p className="coursework-description">{cw.description}</p>
              )}

              <div className="coursework-details">
                <div className="detail-item">
                  <span className="label">Matière:</span>
                  <span>{cw.matiere?.nom}</span>
                </div>
                <div className="detail-item">
                  <span className="label">Points consommés:</span>
                  <span className="points-badge">-{cw.pointsConsommes}pts</span>
                </div>
                <div className="detail-item">
                  <span className="label">Niveau:</span>
                  <span>{cw.niveau_difficulte}/5</span>
                </div>
                {cw.dateEcheance && (
                  <div className="detail-item">
                    <span className="label">Échéance:</span>
                    <span>{new Date(cw.dateEcheance).toLocaleDateString('fr-FR')}</span>
                  </div>
                )}
              </div>

              {!cw.isCompleted && (
                <button
                  className="btn-success btn-block"
                  onClick={() => handleMarkCompleted(cw.id)}
                  disabled={completing === cw.id}
                >
                  {completing === cw.id ? (
                    <><Loader size={16} className="spinner" /> Validation...</>
                  ) : (
                    <><CheckCircle size={16} /> Marquer comme complété</>
                  )}
                </button>
              )}
            </div>
          ))
        )}
      </div>

      <style jsx>{`
        .coursework-panel {
          padding: 20px;
          background: white;
          border-radius: 8px;
          margin-top: 20px;
        }

        .panel-header h3 {
          margin: 0 0 5px 0;
          font-size: 1.2rem;
        }

        .panel-header .text-muted {
          margin: 0;
          color: #64748B;
          font-size: 0.9rem;
        }

        .filter-tabs {
          display: flex;
          gap: 10px;
          border-bottom: 2px solid #e2e8f0;
        }

        .filter-tab {
          padding: 10px 15px;
          border: none;
          background: none;
          cursor: pointer;
          color: #64748B;
          font-weight: 500;
          transition: all 0.3s;
          position: relative;
        }

        .filter-tab.active {
          color: #0F172A;
        }

        .filter-tab.active::after {
          content: '';
          position: absolute;
          bottom: -2px;
          left: 0;
          right: 0;
          height: 2px;
          background: #FF6B35;
        }

        .coursework-list {
          display: flex;
          flex-direction: column;
          gap: 15px;
        }

        .coursework-item {
          border: 1px solid #e2e8f0;
          border-radius: 8px;
          padding: 15px;
          transition: all 0.3s;
          background: #f8fafc;
        }

        .coursework-item.completed {
          opacity: 0.7;
          border-color: #10B981;
          background: #f0fdf4;
        }

        .coursework-title-row {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 10px;
        }

        .coursework-title {
          display: flex;
          align-items: center;
          gap: 10px;
          font-weight: 600;
          font-size: 1rem;
        }

        .check-icon {
          color: #10B981;
        }

        .alert-icon {
          color: #FF6B35;
        }

        .coursework-description {
          margin: 10px 0;
          color: #475569;
          font-size: 0.9rem;
          line-height: 1.5;
        }

        .coursework-details {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
          gap: 12px;
          margin: 15px 0;
          padding: 12px 0;
          border-top: 1px solid #e2e8f0;
          border-bottom: 1px solid #e2e8f0;
        }

        .detail-item {
          display: flex;
          flex-direction: column;
          gap: 4px;
        }

        .detail-item .label {
          font-size: 0.8rem;
          color: #94a3b8;
          font-weight: 600;
          text-transform: uppercase;
        }

        .detail-item span:not(.label) {
          font-size: 0.95rem;
          color: #0F172A;
        }

        .points-badge {
          background: #FEE2E2;
          color: #DC2626;
          padding: 2px 8px;
          border-radius: 4px;
          font-weight: 600;
          display: inline-block;
          width: fit-content;
        }

        .btn-block {
          width: 100%;
          margin-top: 10px;
        }

        .difficulty-badge {
          display: flex;
          gap: 2px;
          color: #FF6B35;
        }

        .empty-state {
          text-align: center;
          padding: 40px 20px;
          color: #64748B;
        }

        .empty-state h4 {
          margin: 0 0 10px 0;
          color: #0F172A;
        }

        .spinner {
          animation: spin 1s linear infinite;
        }

        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default CourseworkReceived;
