import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { X, CheckCircle2, Loader, RotateCcw, Trophy } from 'lucide-react';
import { aiAPI } from '../services/api';

/**
 * Quiz "défi" sur un sujet donné (envoyé par un admin/délégué).
 * Génère un quiz IA sur le sujet, interactif, avec score. Consomme des points.
 * Props : sujet, niveau, onClose, onPointsConsumed()
 */
const QuizDefi = ({ sujet, niveau = 'moyen', onClose, onPointsConsumed }) => {
  const [loading, setLoading] = useState(true);
  const [erreur, setErreur] = useState('');
  const [questions, setQuestions] = useState([]);
  const [reponses, setReponses] = useState({});
  const [fini, setFini] = useState(false);
  const [score, setScore] = useState(0);

  const charger = async () => {
    setLoading(true); setErreur(''); setQuestions([]); setReponses({}); setFini(false);
    try {
      const res = await aiAPI.genererQuiz(sujet, niveau, null);
      const qs = (res.data?.questions || []).slice(0, 5);
      if (qs.length === 0) setErreur(res.data?.error || "L'IA n'a pas pu générer le quiz. Réessaie.");
      else { setQuestions(qs); if (onPointsConsumed) onPointsConsumed(); }
    } catch (e) {
      setErreur(e?.response?.data?.error || 'Erreur. Réessaie dans quelques secondes.');
    } finally { setLoading(false); }
  };

  useEffect(() => { charger(); /* eslint-disable-next-line */ }, []);

  const bonne = (q) => q.reponse_correcte || q.bonne_reponse || q.answer || '';
  const toutRepondu = questions.length > 0 && Object.keys(reponses).length === questions.length;

  const valider = () => {
    let bons = 0;
    questions.forEach((q, i) => { if (reponses[i] != null && String(reponses[i]).trim() === String(bonne(q)).trim()) bons++; });
    setScore(bons / questions.length);
    setFini(true);
  };

  const C = '#F59E0B';
  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      style={{ position: 'fixed', inset: 0, background: 'rgba(2,6,23,0.9)', backdropFilter: 'blur(8px)', zIndex: 9500, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <motion.div initial={{ scale: 0.94, y: 20, opacity: 0 }} animate={{ scale: 1, y: 0, opacity: 1 }}
        style={{ background: 'white', border: '1px solid #e2e8f0', borderRadius: 24, width: '100%', maxWidth: 560, maxHeight: '90vh', overflowY: 'auto', boxShadow: '0 16px 48px rgba(0,0,0,0.1)' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '20px 22px 0' }}>
          <div>
            <h2 style={{ color: '#0f172a', fontWeight: 900, fontSize: '1.1rem', margin: 0 }}>🎯 Défi quiz</h2>
            <p style={{ color: '#475569', fontSize: '0.8rem', margin: '3px 0 0' }}>{sujet}</p>
          </div>
          <button onClick={onClose} style={{ background: '#f1f5f9', border: '1px solid #e2e8f0', borderRadius: 10, width: 34, height: 34, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: '#475569' }}><X size={17} /></button>
        </div>

        <div style={{ padding: '18px 22px 24px' }}>
          {loading && (
            <div style={{ textAlign: 'center', padding: '40px 0', color: '#475569' }}>
              <Loader size={30} style={{ animation: 'spin 1s linear infinite' }} />
              <p style={{ marginTop: 12, fontSize: '0.88rem' }}>L'IA prépare ton défi sur « {sujet} »…</p>
            </div>
          )}

          {erreur && !loading && (
            <div style={{ textAlign: 'center', padding: '24px 0' }}>
              <p style={{ color: '#FCA5A5', fontSize: '0.9rem', marginBottom: 14 }}>{erreur}</p>
              <button onClick={charger} style={btn(C)}><RotateCcw size={16} /> Réessayer</button>
            </div>
          )}

          {!loading && !erreur && !fini && questions.map((q, i) => (
            <div key={i} style={{ marginBottom: 18, padding: 14, borderRadius: 14, background: '#f8fafc', border: '1px solid #e2e8f0' }}>
              <p style={{ color: '#0f172a', fontWeight: 700, fontSize: '0.9rem', margin: '0 0 10px' }}>{i + 1}. {q.question}</p>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 7 }}>
                {(q.options || []).map((opt, j) => {
                  const sel = reponses[i] === opt;
                  return (
                    <button key={j} onClick={() => setReponses(prev => ({ ...prev, [i]: opt }))}
                      style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '10px 12px', borderRadius: 10, border: sel ? `1px solid ${C}` : sel ? `1px solid ${C}` : '1px solid #e2e8f0', background: sel ? `${C}1a` : 'white', color: '#0f172a', cursor: 'pointer', textAlign: 'left', fontSize: '0.85rem' }}>
                      <span style={{ width: 18, height: 18, borderRadius: '50%', border: `2px solid ${sel ? C : '#475569'}`, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        {sel && <span style={{ width: 8, height: 8, borderRadius: '50%', background: C }} />}
                      </span>
                      {opt}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}

          {!loading && !erreur && !fini && questions.length > 0 && (
            <button onClick={valider} disabled={!toutRepondu} style={{ ...btn(C), width: '100%', opacity: toutRepondu ? 1 : 0.5 }}>
              Valider <CheckCircle2 size={16} />
            </button>
          )}

          {fini && (
            <div style={{ textAlign: 'center', padding: '10px 0' }}>
              <div style={{ fontSize: '3rem' }}>{score >= 0.6 ? '🎉' : '💪'}</div>
              <h3 style={{ color: score >= 0.6 ? '#10B981' : '#F59E0B', fontWeight: 900, fontSize: '1.3rem', margin: '6px 0' }}>
                {score >= 0.6 ? 'Bravo !' : 'Continue à réviser !'}
              </h3>
              <p style={{ color: '#E2E8F0', fontSize: '1.1rem', fontWeight: 800, margin: '8px 0 18px' }}>
                Score : {Math.round(score * questions.length)}/{questions.length} ({Math.round(score * 100)}%)
              </p>
              <div style={{ display: 'flex', gap: 10 }}>
                <button onClick={charger} style={{ ...btn(C), flex: 1 }}><RotateCcw size={16} /> Nouveau quiz</button>
                <button onClick={onClose} style={{ ...btn('#A855F7'), flex: 1 }}><Trophy size={16} /> Terminer</button>
              </div>
            </div>
          )}
        </div>
      </motion.div>
    </motion.div>
  );
};

const btn = (color) => ({
  display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
  padding: '12px 18px', borderRadius: 12, border: 'none', cursor: 'pointer',
  fontWeight: 800, fontSize: '0.9rem', background: color, color: '#06121f',
});

export default QuizDefi;
