    const label = `Correction : ${epreuve.titre} (${epreuve.session} ${epreuve.annee})`;
    const history = loadHistory();
    const existing = history.find(h => h.key === key);
    setSelectedEpreuve(epreuve);
    setSelectedCours(coursRef || null);
    setChatLog(existing ? existing.messages : []);
    setChatSessionKey(key);
