  // ── Helper : construit une URL absolue pour un fichier stocké en local (/api/fichiers/...)
  // ou en retourne l'URL Cloudinary telle quelle (déjà absolue).
  const buildFileUrl = (fichierUrl) => {
    if (!fichierUrl) return null;
    // URL Cloudinary ou autre URL absolue → ne pas préfixer
    if (fichierUrl.startsWith('http://') || fichierUrl.startsWith('https://')) return fichierUrl;
    // URL relative (/api/fichiers/...) → préfixer avec l'URL du backend
    return `${BACKEND_BASE_URL}${fichierUrl.startsWith('/') ? fichierUrl : '/' + fichierUrl}`;
  };

