import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Lock, CheckCircle2, Trophy, Zap, ArrowRight, Loader, RotateCcw } from 'lucide-react';
import { aiAPI, BACKEND_BASE_URL } from '../services/api';

/**
 * Évaluation à 5 niveaux progressifs sur un cours.
 * - Chaque niveau = un quiz IA de difficulté croissante généré depuis le cours
 * - Il faut réussir (≥ 60%) un niveau pour débloquer le suivant
 * - Progression sauvegardée par cours (localStorage)
 *
 * Props : cours (titre, fichierUrl, matiere/matiereLibre), onClose, onPointsConsumed()
 */
const NIVEAUX = [
  { n: 1, label: 'Découverte',   difficulte: 'très facile — définitions et notions de base', color: '#10B981' },
  { n: 2, label: 'Compréhension', difficulte: 'facile — comprendre les concepts clés',        color: '#0EA5E9' },
  { n: 3, label: 'Application',    difficulte: 'moyen — appliquer à des cas simples',           color: '#F59E0B' },
  { n: 4, label: 'Analyse',        difficulte: 'difficile — analyser et résoudre des problèmes', color: '#F97316' },
  { n: 5, label: 'Expert',         difficulte: 'expert — synthèse et cas complexes',            color: '#A855F7' },
];
const SEUIL = 0.6; // 60% pour réussir
const NB_Q = 5;

const Evaluation5Niveaux = ({ cours, onClose, onPointsConsumed }) => {
  const progressKey = `eval-progress-${cours?.id}`;
  const [maxDebloque, setMaxDebloque] = useState(1); // niveau max accessible
  const [etape, setEtape] = useState('carte'); // 'carte' | 'quiz' | 'resultat'
  const [niveauActif, setNiveauActif] = useState(null);
  const [questions, setQuestions] = useState([]);
  const [reponses, setReponses] = useState({}); // { qIndex: optionChoisie }
  const [loading, setLoading] = useState(false);
  const [erreur, setErreur] = useState('');
  const [score, setScore] = useState(0);

  // Charger la progression
  useEffect(() => {
    try {
      const saved = JSON.parse(localStorage.getItem(progressKey) || '{}');
      setMaxDebloque(saved.maxDebloque || 1);
    } catch { setMaxDebloque(1); }
  }, [progressKey]);

  const sauverProgression = (niveau) => {
    const nouveauMax = Math.min(5, Math.max(maxDebloque, niveau + 1));
    setMaxDebloque(nouveauMax);
    try { localStorage.setItem(progressKey, JSON.stringify({ maxDebloque: nouveauMax, dernierNiveau: niveau })); } catch {}
  };

  // Lancer un niveau → générer le quiz IA
  const lancerNiveau = async (niveau) => {
    if (niveau.n > maxDebloque) return; // verrouillé
    setNiveauActif(niveau);
    setEtape('quiz');
    setLoading(true);
    setErreur('');
    setReponses({});
    setQuestions([]);
    try {
      const fileUrl = cours.fichierUrl
        ? (cours.fichierUrl.startsWith('http') ? cours.fichierUrl : `${BACKEND_BASE_URL}${cours.fichierUrl.startsWith('/') ? cours.fichierUrl : '/' + cours.fichierUrl}`)
        : null;
      const sujet = `${cours.titre} — Niveau ${niveau.n}/5 (${niveau.label})`;
      const res = await aiAPI.genererQuiz(sujet, niveau.difficulte, fileUrl);
      const data = res.data || {};
      const qs = (data.questions || []).slice(0, NB_Q);
      if (qs.length === 0) {
        setErreur(data.error || "L'IA n'a pas pu générer le quiz. Réessaie.");
      } else {
        setQuestions(qs);
        if (onPointsConsumed) onPointsConsumed();
      }
    } catch (e) {
      setErreur(e?.response?.data?.error || "Erreur de génération. Réessaie dans quelques secondes.");
    } finally {
      setLoading(false);
    }
  };

  // Normalise la bonne réponse pour comparaison
  const bonneReponse = (q) => q.reponse_correcte || q.bonne_reponse || q.answer || '';

  const valider = () => {
    let bons = 0;
    questions.forEach((q, i) => {
      const choisi = reponses[i];
      if (choisi != null && String(choisi).trim() === String(bonneReponse(q)).trim()) bons++;
    });
    const sc = bons / questions.length;
    setScore(sc);
    setEtape('resultat');
    if (sc >= SEUIL && niveauActif) sauverProgression(niveauActif.n);
  };

  const toutRepondu = questions.length > 0 && Object.keys(reponses).length === questions.length;

  return (
    <motion.div
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      style={{ position: 'fixed', inset: 0, background: 'rgba(2,6,23,0.9)', backdropFilter: 'blur(8px)',
        zIndex: 9500, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <motion.div
        initial={{ scale: 0.94, y: 20, opacity: 0 }} animate={{ scale: 1, y: 0, opacity: 1 }}
        style={{ background: 'white', border: '1px solid #e2e8f0',
          borderRadius: 24, width: '100%', maxWidth: 560, maxHeight: '90vh', overflowY: 'auto',
          boxShadow: '0 30px 80px rgba(0,0,0,0.6)' }}>

        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '20px 22px 0' }}>
          <div>
            <h2 style={{ color: '#0f172a', fontWeight: 900, fontSize: '1.15rem', margin: 0 }}>🎯 Évaluation 5 niveaux</h2>
            <p style={{ color: '#475569', fontSize: '0.8rem', margin: '3px 0 0' }}>{cours?.titre}</p>
          </div>
          <button onClick={onClose} style={{ background: '#f1f5f9', border: 'none', borderRadius: 10, width: 34, height: 34, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: '#475569' }}><X size={17} /></button>
        </div>

        <div style={{ padding: '18px 22px 24px' }}>
          <AnimatePresence mode="wait">

            {/* ── CARTE DES NIVEAUX ── */}
            {etape === 'carte' && (
              <motion.div key="carte" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                <p style={{ color: '#475569', fontSize: '0.85rem', margin: '0 0 16px', lineHeight: 1.5 }}>
                  Progresse niveau par niveau. Réussis chaque quiz (≥ 60%) pour débloquer le suivant. 🚀
                </p>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                  {NIVEAUX.map(niv => {
                    const debloque = niv.n <= maxDebloque;
                    const reussi = niv.n < maxDebloque;
                    return (
                      <button key={niv.n} disabled={!debloque} onClick={() => lancerNiveau(niv)}
                        style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '14px 16px', borderRadius: 16,
                          border: `1px solid ${debloque ? niv.color + '55' : '#f1f5f9'}`,
                          background: debloque ? `${niv.color}12` : '#f8fafc',
                          cursor: debloque ? 'pointer' : 'not-allowed', opacity: debloque ? 1 : 0.5, textAlign: 'left', width: '100%' }}>
                        <div style={{ width: 42, height: 42, borderRadius: 12, background: `${niv.color}22`, color: niv.color,
                          display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 900, fontSize: '1.1rem', flexShrink: 0 }}>
                          {reussi ? <CheckCircle2 size={22} /> : debloque ? niv.n : <Lock size={18} />}
                        </div>
                        <div style={{ flex: 1 }}>
                          <div style={{ color: '#0f172a', fontWeight: 800, fontSize: '0.92rem' }}>Niveau {niv.n} — {niv.label}</div>
                          <div style={{ color: '#475569', fontSize: '0.74rem' }}>{reussi ? '✅ Réussi' : debloque ? 'Disponible' : 'Verrouillé'}</div>
                        </div>
                        {debloque && !reussi && <ArrowRight size={18} color={niv.color} />}
                        {reussi && <Trophy size={18} color={niv.color} />}
                      </button>
                    );
                  })}
                </div>
              </motion.div>
            )}

            {/* ── QUIZ ── */}
            {etape === 'quiz' && niveauActif && (
              <motion.div key="quiz" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 14 }}>
                  <span style={{ background: `${niveauActif.color}22`, color: niveauActif.color, fontWeight: 800, fontSize: '0.78rem', padding: '4px 12px', borderRadius: 8 }}>
                    Niveau {niveauActif.n} — {niveauActif.label}
                  </span>
                </div>

                {loading && (
                  <div style={{ textAlign: 'center', padding: '40px 0', color: '#475569' }}>
                    <Loader size={30} className="spinner" style={{ animation: 'spin 1s linear infinite' }} />
                    <p style={{ marginTop: 12, fontSize: '0.88rem' }}>L'IA prépare ton quiz de niveau {niveauActif.n}…</p>
                  </div>
                )}

                {erreur && !loading && (
                  <div style={{ textAlign: 'center', padding: '24px 0' }}>
                    <p style={{ color: '#FCA5A5', fontSize: '0.9rem', marginBottom: 14 }}>{erreur}</p>
                    <button onClick={() => lancerNiveau(niveauActif)} style={btnPrimaire(niveauActif.color)}>
                      <RotateCcw size={16} /> Réessayer
                    </button>
                  </div>
                )}

                {!loading && !erreur && questions.map((q, i) => (
                  <div key={i} style={{ marginBottom: 18, padding: 14, borderRadius: 14, background: '#f8fafc', border: '1px solid #e2e8f0' }}>
                    <p style={{ color: '#0f172a', fontWeight: 700, fontSize: '0.9rem', margin: '0 0 10px' }}>
                      {i + 1}. {q.question}
                    </p>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 7 }}>
                      {(q.options || []).map((opt, j) => {
                        const choisi = reponses[i] === opt;
                        return (
                          <button key={j} onClick={() => setReponses(prev => ({ ...prev, [i]: opt }))}
                            style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '10px 12px', borderRadius: 10,
                              border: choisi ? `1px solid ${niveauActif.color}` : '1px solid #e2e8f0',
                              background: choisi ? `${niveauActif.color}1a` : '#f8fafc',
                              color: '#E2E8F0', cursor: 'pointer', textAlign: 'left', fontSize: '0.85rem' }}>
                            <span style={{ width: 18, height: 18, borderRadius: '50%', border: `2px solid ${choisi ? niveauActif.color : '#475569'}`, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                              {choisi && <span style={{ width: 8, height: 8, borderRadius: '50%', background: niveauActif.color }} />}
                            </span>
                            {opt}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                ))}

                {!loading && !erreur && questions.length > 0 && (
                  <div style={{ display: 'flex', gap: 10, marginTop: 8 }}>
                    <button onClick={() => setEtape('carte')} style={btnSecondaire()}>Retour</button>
                    <button onClick={valider} disabled={!toutRepondu} style={{ ...btnPrimaire(niveauActif.color), flex: 1, opacity: toutRepondu ? 1 : 0.5 }}>
                      Valider mes réponses <CheckCircle2 size={16} />
                    </button>
                  </div>
                )}
              </motion.div>
            )}

            {/* ── RÉSULTAT ── */}
            {etape === 'resultat' && niveauActif && (
              <motion.div key="resultat" initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} style={{ textAlign: 'center', padding: '10px 0' }}>
                {score >= SEUIL ? (
                  <>
                    <div style={{ fontSize: '3rem', marginBottom: 8 }}>🎉</div>
                    <h3 style={{ color: '#10B981', fontWeight: 900, fontSize: '1.3rem', margin: 0 }}>Niveau réussi !</h3>
                  </>
                ) : (
                  <>
                    <div style={{ fontSize: '3rem', marginBottom: 8 }}>💪</div>
                    <h3 style={{ color: '#F59E0B', fontWeight: 900, fontSize: '1.3rem', margin: 0 }}>Presque !</h3>
                  </>
                )}
                <p style={{ color: '#E2E8F0', fontSize: '1.1rem', fontWeight: 800, margin: '12px 0 4px' }}>
                  Score : {Math.round(score * questions.length)}/{questions.length} ({Math.round(score * 100)}%)
                </p>
                <p style={{ color: '#475569', fontSize: '0.85rem', margin: '0 0 20px' }}>
                  {score >= SEUIL
                    ? (niveauActif.n < 5 ? `Niveau ${niveauActif.n + 1} débloqué ! 🔓` : 'Tu as terminé les 5 niveaux ! 🏆')
                    : 'Il faut 60% pour valider. Révise et réessaie !'}
                </p>
                <div style={{ display: 'flex', gap: 10 }}>
                  <button onClick={() => setEtape('carte')} style={{ ...btnSecondaire(), flex: 1 }}>Voir les niveaux</button>
                  {score < SEUIL
                    ? <button onClick={() => lancerNiveau(niveauActif)} style={{ ...btnPrimaire(niveauActif.color), flex: 1 }}><RotateCcw size={16} /> Réessayer</button>
                    : niveauActif.n < 5
                      ? <button onClick={() => lancerNiveau(NIVEAUX[niveauActif.n])} style={{ ...btnPrimaire(NIVEAUX[niveauActif.n].color), flex: 1 }}>Niveau suivant <ArrowRight size={16} /></button>
                      : <button onClick={onClose} style={{ ...btnPrimaire('#A855F7'), flex: 1 }}><Trophy size={16} /> Terminer</button>}
                </div>
              </motion.div>
            )}

          </AnimatePresence>
        </div>
      </motion.div>
    </motion.div>
  );
};

const btnPrimaire = (color) => ({
  display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
  padding: '12px 18px', borderRadius: 12, border: 'none', cursor: 'pointer',
  fontWeight: 800, fontSize: '0.9rem', background: color, color: '#06121f',
});
const btnSecondaire = () => ({
  display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
  padding: '12px 18px', borderRadius: 12, border: '1px solid #e2e8f0',
  background: '#f8fafc', color: '#475569', cursor: 'pointer', fontWeight: 700, fontSize: '0.88rem',
});

export default Evaluation5Niveaux;
