import React, { useState } from 'react';
import { ArrowLeft, FileText, FolderOpen, Send } from 'lucide-react';
import TravailEtudiantUploader from './TravailEtudiantUploader';
import DocumentsUploader from './DocumentsUploader';
import MesSoumissionsPanel from './MesSoumissionsPanel';

const TABS = [
  { key: 'travaux', label: 'Mes travaux', icon: <FileText size={16} /> },
  { key: 'documents', label: 'Mes documents', icon: <FolderOpen size={16} /> },
  { key: 'soumissions', label: 'Soumissions', icon: <Send size={16} /> },
];

/**
 * Hub étudiant : travaux, documents nommés, soumissions pour correction.
 */
const MesDevoirs = ({ user, onBack }) => {
  const [tab, setTab] = useState('travaux');

  return (
    <div className="view-container" style={{ padding: '0 0 24px' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '16px', padding: '0 16px' }}>
        {onBack && (
          <button
            type="button"
            onClick={onBack}
            style={{
              display: 'flex', alignItems: 'center', gap: '6px',
              background: '#f1f5f9', border: '1px solid #e2e8f0',
              borderRadius: '10px', padding: '8px 14px', color: '#475569', cursor: 'pointer',
              fontWeight: 700, fontSize: '0.82rem',
            }}
          >
            <ArrowLeft size={16} /> Retour
          </button>
        )}
        <h2 style={{ margin: 0, fontSize: '1.2rem', fontWeight: 800, color: '#0c1730' }}>📝 Mes Devoirs</h2>
      </div>

      <div style={{
        display: 'flex', gap: '8px', padding: '0 16px 16px', overflowX: 'auto',
        borderBottom: '1px solid #f1f5f9',
      }}>
        {TABS.map((t) => (
          <button
            key={t.key}
            type="button"
            onClick={() => setTab(t.key)}
            style={{
              display: 'flex', alignItems: 'center', gap: '6px', whiteSpace: 'nowrap',
              padding: '10px 16px', borderRadius: '10px', border: 'none', cursor: 'pointer',
              fontWeight: 700, fontSize: '0.82rem',
              background: tab === t.key ? 'rgba(56,189,248,0.2)' : '#f8fafc',
              color: tab === t.key ? '#38BDF8' : '#94A3B8',
            }}
          >
            {t.icon} {t.label}
          </button>
        ))}
      </div>

      <div style={{
        background: '#f8fafc', borderRadius: '16px',
        margin: '16px', border: '1px solid #e2e8f0',
        minHeight: '200px',
      }}>
        {tab === 'travaux' && <TravailEtudiantUploader user={user} />}
        {tab === 'documents' && <DocumentsUploader user={user} />}
        {tab === 'soumissions' && <MesSoumissionsPanel user={user} />}
      </div>
    </div>
  );
};

export default MesDevoirs;
