import React, { useState, useEffect } from 'react';
import { Upload, FileText, Download, Trash2, AlertCircle, Loader, CheckCircle } from 'lucide-react';
import { travauxAPI, academicAPI, fileAPI, BACKEND_BASE_URL } from '../services/api';

/**
 * TravailEtudiantUploader - Interface pour les étudiants d'uploader leurs travaux
 * Support: PDF, Word, Excel, PowerPoint, images, etc.
 */
const TravailEtudiantUploader = ({ user }) => {
  const [matieres, setMatieres] = useState([]);
  const [travaux, setTravaux] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [uploadingFile, setUploadingFile] = useState(false);

  const [formData, setFormData] = useState({
    titre: '',
    description: '',
    matiereId: '',
    fichierUrl: '',
    format: 'PDF'
  });

  useEffect(() => {
    loadData();
  }, [user?.id]);

  const loadData = async () => {
    try {
      setLoading(true);
      const [travRes, matRes] = await Promise.all([
        travauxAPI.getMesTravaux(user.id),
        academicAPI.getMatieres()
      ]);
      setTravaux(travRes.data || []);
      setMatieres(matRes.data || []);
    } catch (err) {
      setError('Erreur lors du chargement des données');
    } finally {
      setLoading(false);
    }
  };

  const handleFilePick = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      setUploadingFile(true);
      setError('');
      const fd = new FormData();
      fd.append('file', file);
      const res = await fileAPI.uploadFile(fd);
      const url = res.data?.url || res.data?.path || res.data;
      const fullUrl = typeof url === 'string' && url.startsWith('http') ? url : `${BACKEND_BASE_URL}${url}`;
      const ext = file.name.split('.').pop()?.toUpperCase() || 'PDF';
      setFormData((prev) => ({
        ...prev,
        fichierUrl: fullUrl,
        format: ext.length <= 5 ? ext : 'PDF',
        taille: file.size,
      }));
    } catch {
      setError('Échec de l\'upload du fichier');
    } finally {
      setUploadingFile(false);
    }
  };

  const handleUpload = async (e) => {
    e.preventDefault();
    if (!formData.titre || !formData.matiereId || !formData.fichierUrl) {
      setError('Veuillez remplir tous les champs requis');
      return;
    }

    try {
      setLoading(true);
      setError('');

      await travauxAPI.uploadTravail({
        matiereId: formData.matiereId,
        titre: formData.titre,
        description: formData.description,
        fichierUrl: formData.fichierUrl,
        format: formData.format,
        taille: 0
      });

      setFormData({ titre: '', description: '', matiereId: '', fichierUrl: '', format: 'PDF' });
      setShowForm(false);
      setSuccess('✅ Travail uploadé avec succès!');
      await loadData();
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError('Erreur lors de l\'upload');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (travailId) => {
    if (window.confirm('Supprimer ce travail?')) {
      try {
        await travauxAPI.deleteTravail(travailId);
        await loadData();
      } catch (err) {
        setError('Erreur lors de la suppression');
      }
    }
  };

  const getFormatIcon = (format) => {
    const icons = {
      PDF: '📄', DOCX: '📘', DOC: '📘', XLSX: '📊', XLS: '📊',
      PPTX: '🎠', PPT: '🎠', JPEG: '🖼️', PNG: '🖼️', JPG: '🖼️',
      GIF: '🖼️', TXT: '📝', RTF: '📝', ODT: '📘', ODS: '📊', ODP: '🎠'
    };
    return icons[format] || '📎';
  };

  const getStatutBadge = (statut) => {
    const styles = {
      SOUMIS: { bg: '#fef3c7', color: '#92400e', label: '📥 Soumis' },
      EN_EVALUATION: { bg: '#dbeafe', color: '#1e40af', label: '⏳ En évaluation' },
      EVALUE: { bg: '#f0fdf4', color: '#15803d', label: '✅ Évalué' }
    };
    const style = styles[statut] || styles.SOUMIS;
    return (
      <span style={{ background: style.bg, color: style.color, padding: '4px 10px', borderRadius: '4px', fontSize: '0.8rem', fontWeight: 700 }}>
        {style.label}
      </span>
    );
  };

  if (loading) return <div style={{ padding: '20px', textAlign: 'center' }}><Loader className="spinner" /> Chargement...</div>;

  return (
    <div style={{ padding: '20px' }}>
      <div style={{ marginBottom: '20px' }}>
        <h3 style={{ margin: '0 0 10px 0', fontSize: '1.2rem', fontWeight: 700 }}>📚 Mes Travaux</h3>
        <p style={{ margin: 0, color: '#666', fontSize: '0.9rem' }}>
          Uploadez vos travaux en PDF, Word, Excel, PowerPoint ou image
        </p>
      </div>

      {error && (
        <div style={{ background: '#fee', padding: '12px 15px', borderRadius: '8px', marginBottom: '15px', color: '#c33', display: 'flex', gap: '10px' }}>
          <AlertCircle size={18} style={{ flexShrink: 0 }} />
          {error}
        </div>
      )}

      {success && (
        <div style={{ background: '#f0fdf4', padding: '12px 15px', borderRadius: '8px', marginBottom: '15px', color: '#10b981', display: 'flex', gap: '10px' }}>
          <CheckCircle size={18} style={{ flexShrink: 0 }} />
          {success}
        </div>
      )}

      {/* Bouton Upload */}
      <button
        onClick={() => setShowForm(!showForm)}
        style={{
          background: '#3B82F6',
          color: 'white',
          border: 'none',
          padding: '12px 20px',
          borderRadius: '8px',
          cursor: 'pointer',
          fontWeight: 600,
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          marginBottom: '20px'
        }}
      >
        <Upload size={18} /> Uploader un travail
      </button>

      {/* Formulaire */}
      {showForm && (
        <div style={{ background: 'white', padding: '20px', borderRadius: '10px', marginBottom: '20px', border: '1px solid #ddd' }}>
          <h4 style={{ margin: '0 0 15px 0', fontWeight: 700 }}>📝 Nouveau Travail</h4>
          <form onSubmit={handleUpload}>
            <div style={{ marginBottom: '15px' }}>
              <label style={{ display: 'block', fontWeight: 600, marginBottom: '5px' }}>Titre *</label>
              <input
                type="text"
                placeholder="Ex: Devoir Mathématiques - Chapitre 5"
                value={formData.titre}
                onChange={(e) => setFormData({ ...formData, titre: e.target.value })}
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px', boxSizing: 'border-box' }}
                required
              />
            </div>

            <div style={{ marginBottom: '15px' }}>
              <label style={{ display: 'block', fontWeight: 600, marginBottom: '5px' }}>Matière *</label>
              <select
                value={formData.matiereId}
                onChange={(e) => setFormData({ ...formData, matiereId: e.target.value })}
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }}
                required
              >
                <option value="">Sélectionner une matière</option>
                {matieres.map(m => (
                  <option key={m.id} value={m.id}>{m.nom}</option>
                ))}
              </select>
            </div>

            <div style={{ marginBottom: '15px' }}>
              <label style={{ display: 'block', fontWeight: 600, marginBottom: '5px' }}>Description (optionnel)</label>
              <textarea
                placeholder="Notes sur ce travail..."
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                rows="3"
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px', boxSizing: 'border-box', fontFamily: 'inherit' }}
              />
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginBottom: '15px' }}>
              <div>
                <label style={{ display: 'block', fontWeight: 600, marginBottom: '5px' }}>Format *</label>
                <select
                  value={formData.format}
                  onChange={(e) => setFormData({ ...formData, format: e.target.value })}
                  style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }}
                >
                  <optgroup label="📄 Documents">
                    <option value="PDF">PDF</option>
                    <option value="DOCX">Word (.docx)</option>
                    <option value="DOC">Word (.doc)</option>
                    <option value="TXT">Texte brut</option>
                    <option value="RTF">Rich Text</option>
                    <option value="ODT">OpenDocument</option>
                  </optgroup>
                  <optgroup label="📊 Feuilles de calcul">
                    <option value="XLSX">Excel (.xlsx)</option>
                    <option value="XLS">Excel (.xls)</option>
                    <option value="ODS">OpenCalc</option>
                  </optgroup>
                  <optgroup label="🎠 Présentations">
                    <option value="PPTX">PowerPoint (.pptx)</option>
                    <option value="PPT">PowerPoint (.ppt)</option>
                    <option value="ODP">OpenPresentation</option>
                  </optgroup>
                  <optgroup label="🖼️ Images">
                    <option value="JPEG">JPEG</option>
                    <option value="PNG">PNG</option>
                    <option value="JPG">JPG</option>
                    <option value="GIF">GIF</option>
                  </optgroup>
                  <option value="AUTRE">Autre</option>
                </select>
              </div>

              <div>
                <label style={{ display: 'block', fontWeight: 600, marginBottom: '5px' }}>Fichier *</label>
                <input
                  type="file"
                  accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.png,.jpg,.jpeg"
                  onChange={handleFilePick}
                  disabled={uploadingFile}
                  style={{ width: '100%', fontSize: '0.85rem' }}
                />
                {formData.fichierUrl && (
                  <p style={{ fontSize: '0.78rem', color: '#10b981', margin: '6px 0 0' }}>✓ Fichier prêt</p>
                )}
                {uploadingFile && <p style={{ fontSize: '0.78rem', color: '#666' }}>Upload en cours…</p>}
              </div>
            </div>

            <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
              <button
                type="button"
                onClick={() => setShowForm(false)}
                style={{ padding: '10px 20px', background: '#f0f0f0', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 600 }}
              >
                Annuler
              </button>
              <button
                type="submit"
                disabled={loading}
                style={{ padding: '10px 20px', background: '#10B981', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 600 }}
              >
                {loading ? <Loader className="spinner" /> : 'Uploader'}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Liste des travaux */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        {travaux.length === 0 ? (
          <div style={{ padding: '40px 20px', textAlign: 'center', color: '#999', background: '#f8f9fa', borderRadius: '8px' }}>
            <div style={{ fontSize: '2rem', marginBottom: '10px' }}>📚</div>
            <p style={{ margin: 0, fontWeight: 600 }}>Aucun travail uploadé</p>
          </div>
        ) : (
          travaux.map(t => (
            <div
              key={t.id}
              style={{
                background: 'white',
                padding: '15px',
                borderRadius: '8px',
                border: '1px solid #eee',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}
            >
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '8px' }}>
                  <span style={{ fontSize: '1.5rem' }}>{getFormatIcon(t.format)}</span>
                  <strong>{t.titre}</strong>
                  {getStatutBadge(t.statut)}
                </div>
                <p style={{ margin: '0 0 8px 0', color: '#666', fontSize: '0.9rem' }}>
                  {t.matiere?.nom} • {new Date(t.dateCreation).toLocaleDateString('fr-FR')}
                </p>
                {t.description && <p style={{ margin: '0', color: '#666', fontSize: '0.9rem' }}>{t.description}</p>}
                {t.noteObtenue !== null && (
                  <p style={{ margin: '8px 0 0', color: '#10b981', fontWeight: 700 }}>
                    📊 Note: {t.noteObtenue}/20
                  </p>
                )}
              </div>

              <div style={{ display: 'flex', gap: '8px' }}>
                {t.fichierUrl && (
                  <a
                    href={t.fichierUrl}
                    download
                    style={{
                      padding: '8px 12px',
                      background: '#dbeafe',
                      color: '#1e40af',
                      textDecoration: 'none',
                      borderRadius: '6px',
                      cursor: 'pointer',
                      fontWeight: 600,
                      fontSize: '0.85rem',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '5px'
                    }}
                  >
                    <Download size={14} /> Télécharger
                  </a>
                )}
                <button
                  onClick={() => handleDelete(t.id)}
                  style={{
                    padding: '8px 12px',
                    background: '#fee',
                    border: '1px solid #fcc',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    color: '#c33',
                    fontWeight: 600,
                    fontSize: '0.85rem'
                  }}
                >
                  <Trash2 size={14} />
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      <style jsx>{`
        .spinner {
          animation: spin 1s linear infinite;
        }
        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default TravailEtudiantUploader;
