import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Sparkles, BookOpen, Brain, Users, ChevronRight, X, Zap } from 'lucide-react';

const STEPS = [
  {
    icon: <Sparkles size={32} color="#FFD700" />,
    title: 'Bienvenue sur RevisIA_H24 !',
    text: 'Votre assistant IA pour réviser, générer des quiz et corriger vos épreuves — disponible 24h/24 sur mobile et web.',
    cta: 'Suivant',
  },
  {
    icon: <BookOpen size={32} color="#38BDF8" />,
    title: 'Importez vos cours',
    text: 'Allez dans « Mes Cours », choisissez votre matière et importez un PDF ou une photo. L\'IA génère résumés et fiches en quelques secondes.',
    cta: 'Suivant',
  },
  {
    icon: <Brain size={32} color="#A855F7" />,
    title: 'Essayez l\'Assistant IA',
    text: 'Appuyez sur le bouton violet flottant ou ouvrez « Assistant IA » pour poser une question, générer un quiz ou corriger une épreuve.',
    cta: 'Suivant',
  },
  {
    icon: <Users size={32} color="#10B981" />,
    title: 'Déposez vos devoirs',
    text: 'Dans « Mes Devoirs », envoyez vos travaux à votre professeur et soumettez vos copies pour correction. Bonne révision !',
    cta: 'C\'est parti !',
  },
];

/**
 * Parcours guidé 4 étapes — affiché après la première inscription étudiant.
 */
const OnboardingGuide = ({ open, onClose, onGoToView }) => {
  const [step, setStep] = useState(0);
  if (!open) return null;

  const current = STEPS[step];
  const isLast = step === STEPS.length - 1;

  const handleNext = () => {
    if (isLast) {
      onClose();
      if (onGoToView) onGoToView('sessions');
      return;
    }
    setStep((s) => s + 1);
  };

  const handleSkip = () => {
    onClose();
  };

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        style={{
          position: 'fixed', inset: 0, zIndex: 10000,
          background: 'rgba(2,6,23,0.88)', backdropFilter: 'blur(8px)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          padding: '20px',
        }}
      >
        <motion.div
          initial={{ scale: 0.92, y: 24 }}
          animate={{ scale: 1, y: 0 }}
          exit={{ scale: 0.92, y: 24 }}
          style={{
            width: '100%', maxWidth: '420px',
            background: 'white',
            borderRadius: '20px',
            border: '1px solid #e2e8f0',
            boxShadow: '0 16px 48px rgba(0,0,0,0.1)',
            padding: '28px 24px 24px',
            position: 'relative',
          }}
        >
          <button
            type="button"
            onClick={handleSkip}
            aria-label="Fermer"
            style={{
              position: 'absolute', top: '14px', right: '14px',
              background: '#f1f5f9', border: '1px solid #e2e8f0',
              borderRadius: '50%', width: '36px', height: '36px',
              cursor: 'pointer', color: '#475569', display: 'flex',
              alignItems: 'center', justifyContent: 'center',
            }}
          >
            <X size={18} />
          </button>

          <div style={{ textAlign: 'center', marginBottom: '20px' }}>
            <div style={{
              width: '64px', height: '64px', borderRadius: '16px',
              background: 'rgba(56,189,248,0.12)', display: 'flex',
              alignItems: 'center', justifyContent: 'center',
              margin: '0 auto 16px',
            }}>
              {current.icon}
            </div>
            <div style={{ display: 'flex', justifyContent: 'center', gap: '6px', marginBottom: '16px' }}>
              {STEPS.map((_, i) => (
                <span
                  key={i}
                  style={{
                    width: i === step ? '24px' : '8px', height: '8px', borderRadius: '4px',
                    background: i <= step ? '#0ea5e9' : '#e2e8f0',
                    transition: 'all 0.3s',
                  }}
                />
              ))}
            </div>
            <h2 style={{ color: '#0f172a', fontSize: '1.25rem', fontWeight: 800, margin: '0 0 10px' }}>
              {current.title}
            </h2>
            <p style={{ color: '#475569', fontSize: '0.92rem', lineHeight: 1.55, margin: 0 }}>
              {current.text}
            </p>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            <button
              type="button"
              onClick={handleNext}
              style={{
                width: '100%', padding: '14px', borderRadius: '12px', border: 'none',
                background: 'linear-gradient(135deg, #0EA5E9, #8B5CF6)',
                color: 'white', fontWeight: 800, fontSize: '0.95rem',
                cursor: 'pointer', display: 'flex', alignItems: 'center',
                justifyContent: 'center', gap: '8px',
              }}
            >
              {isLast ? <><Zap size={18} /> {current.cta}</> : <>{current.cta} <ChevronRight size={18} /></>}
            </button>
            {!isLast && (
              <button
                type="button"
                onClick={handleSkip}
                style={{
                  background: 'transparent', border: 'none', color: '#475569',
                  fontSize: '0.85rem', cursor: 'pointer', padding: '8px',
                }}
              >
                Passer l'introduction
              </button>
            )}
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

export default OnboardingGuide;
