import React, { useState, useEffect } from 'react';
import { Upload, Trash2, Search, Filter, AlertCircle, Loader } from 'lucide-react';
import { documentsAPI } from '../services/api';

/**
 * DocumentsUploader - Permet aux étudiants d'uploader des documents nommés
 * Avec titre/description pour pouvoir trier et rechercher
 */
const DocumentsUploader = ({ user }) => {
  const [documents, setDocuments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState('all');

  const [formData, setFormData] = useState({
    titre: '',
    description: '',
    fichierUrl: '',
    typeDocument: 'COURS',
    tags: ''
  });

  useEffect(() => {
    loadDocuments();
  }, [user?.id]);

  const loadDocuments = async () => {
    try {
      setLoading(true);
      const res = await documentsAPI.getMesDocuments(user.id);
      setDocuments(res.data || []);
    } catch (err) {
      setError('Erreur lors du chargement des documents');
    } finally {
      setLoading(false);
    }
  };

  const handleUpload = async (e) => {
    e.preventDefault();
    if (!formData.titre) {
      setError('Le titre est requis');
      return;
    }

    try {
      setLoading(true);
      await documentsAPI.uploadDocument({
        titre: formData.titre,
        description: formData.description,
        fichierUrl: formData.fichierUrl,
        typeDocument: formData.typeDocument,
        tags: formData.tags,
        taille: 0 // À implémenter avec upload réel
      });

      setFormData({ titre: '', description: '', fichierUrl: '', typeDocument: 'COURS', tags: '' });
      setShowForm(false);
      await loadDocuments();
    } catch (err) {
      setError('Erreur lors de l\'upload');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (docId) => {
    if (window.confirm('Supprimer ce document?')) {
      try {
        await documentsAPI.deleteDocument(docId);
        await loadDocuments();
      } catch (err) {
        setError('Erreur lors de la suppression');
      }
    }
  };

  // Filtrer et rechercher
  const filtered = documents.filter(doc => {
    const matchSearch = doc.titre.toLowerCase().includes(searchTerm.toLowerCase());
    const matchType = filterType === 'all' || doc.typeDocument === filterType;
    return matchSearch && matchType;
  });

  if (loading) return <div className="panel"><Loader className="spinner" /> Chargement...</div>;

  return (
    <div className="documents-panel" style={{ padding: '20px', background: '#f8f9fa', borderRadius: '12px', marginBottom: '20px' }}>
      <div className="panel-header" style={{ marginBottom: '20px' }}>
        <h3 style={{ margin: 0, fontSize: '1.2rem', fontWeight: 700 }}>📎 Mes Documents</h3>
        <p style={{ margin: '5px 0 0', color: '#666', fontSize: '0.9rem' }}>
          Uploadez vos documents avec un titre pour les organiser
        </p>
      </div>

      {error && (
        <div style={{ background: '#fee', padding: '10px 15px', borderRadius: '8px', marginBottom: '15px', color: '#c33', display: 'flex', gap: '10px', alignItems: 'center' }}>
          <AlertCircle size={18} /> {error}
        </div>
      )}

      {/* Bouton Upload */}
      <button
        onClick={() => setShowForm(!showForm)}
        style={{
          background: '#3B82F6',
          color: 'white',
          border: 'none',
          padding: '10px 20px',
          borderRadius: '8px',
          cursor: 'pointer',
          fontWeight: 600,
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          marginBottom: '20px'
        }}
      >
        <Upload size={18} /> Uploader un document
      </button>

      {/* Formulaire Upload */}
      {showForm && (
        <div style={{ background: 'white', padding: '20px', borderRadius: '8px', marginBottom: '20px', border: '1px solid #ddd' }}>
          <h4 style={{ margin: '0 0 15px 0' }}>📝 Nouveau Document</h4>
          <form onSubmit={handleUpload}>
            <div style={{ marginBottom: '12px' }}>
              <label style={{ display: 'block', fontWeight: 600, marginBottom: '5px' }}>Titre *</label>
              <input
                type="text"
                placeholder="Ex: Algèbre Linéaire - Chapitre 3"
                value={formData.titre}
                onChange={(e) => setFormData({ ...formData, titre: e.target.value })}
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px', boxSizing: 'border-box' }}
                required
              />
            </div>

            <div style={{ marginBottom: '12px' }}>
              <label style={{ display: 'block', fontWeight: 600, marginBottom: '5px' }}>Description</label>
              <textarea
                placeholder="Notes supplémentaires sur ce document..."
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                rows="3"
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px', boxSizing: 'border-box', fontFamily: 'inherit' }}
              />
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginBottom: '12px' }}>
              <div>
                <label style={{ display: 'block', fontWeight: 600, marginBottom: '5px' }}>Type</label>
                <select
                  value={formData.typeDocument}
                  onChange={(e) => setFormData({ ...formData, typeDocument: e.target.value })}
                  style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }}
                >
                  <option value="COURS">📚 Cours</option>
                  <option value="EXERCISE">🔢 Exercice</option>
                  <option value="PROJET">🎯 Projet</option>
                  <option value="AUTRE">📄 Autre</option>
                </select>
              </div>

              <div>
                <label style={{ display: 'block', fontWeight: 600, marginBottom: '5px' }}>Tags</label>
                <input
                  type="text"
                  placeholder="Ex: important, revision, exam"
                  value={formData.tags}
                  onChange={(e) => setFormData({ ...formData, tags: e.target.value })}
                  style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px', boxSizing: 'border-box' }}
                />
              </div>
            </div>

            <div style={{ marginBottom: '12px' }}>
              <label style={{ display: 'block', fontWeight: 600, marginBottom: '5px' }}>URL du fichier</label>
              <input
                type="url"
                placeholder="URL du fichier uploadé"
                value={formData.fichierUrl}
                onChange={(e) => setFormData({ ...formData, fichierUrl: e.target.value })}
                style={{ width: '100%', padding: '10px', border: '1px solid #ddd', borderRadius: '6px', boxSizing: 'border-box' }}
              />
            </div>

            <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
              <button
                type="button"
                onClick={() => setShowForm(false)}
                style={{ padding: '10px 20px', background: '#f0f0f0', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 600 }}
              >
                Annuler
              </button>
              <button
                type="submit"
                disabled={loading}
                style={{ padding: '10px 20px', background: '#10B981', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 600 }}
              >
                {loading ? <Loader className="spinner" /> : 'Uploader'}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Filtres et recherche */}
      <div style={{ display: 'flex', gap: '10px', marginBottom: '15px', flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: '200px', display: 'flex', alignItems: 'center', gap: '8px', background: 'white', padding: '8px 12px', borderRadius: '6px', border: '1px solid #ddd' }}>
          <Search size={16} style={{ color: '#999' }} />
          <input
            type="text"
            placeholder="Rechercher par titre..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{ border: 'none', outline: 'none', flex: 1, background: 'transparent' }}
          />
        </div>

        <select
          value={filterType}
          onChange={(e) => setFilterType(e.target.value)}
          style={{ padding: '8px 12px', border: '1px solid #ddd', borderRadius: '6px', background: 'white', cursor: 'pointer' }}
        >
          <option value="all">Tous les types</option>
          <option value="COURS">📚 Cours</option>
          <option value="EXERCISE">🔢 Exercices</option>
          <option value="PROJET">🎯 Projets</option>
          <option value="AUTRE">📄 Autres</option>
        </select>
      </div>

      {/* Liste des documents */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        {filtered.length === 0 ? (
          <div style={{ padding: '30px 20px', textAlign: 'center', color: '#999', background: 'white', borderRadius: '8px', border: '1px dashed #ddd' }}>
            <div style={{ fontSize: '2rem', marginBottom: '10px' }}>📎</div>
            <p style={{ margin: 0, fontWeight: 600 }}>{searchTerm || filterType !== 'all' ? 'Aucun document trouvé' : 'Aucun document uploadé'}</p>
          </div>
        ) : (
          filtered.map(doc => (
            <div
              key={doc.id}
              style={{
                background: 'white',
                padding: '15px',
                borderRadius: '8px',
                border: '1px solid #eee',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}
            >
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 600, marginBottom: '5px' }}>{doc.titre}</div>
                {doc.description && <p style={{ margin: '0 0 8px 0', color: '#666', fontSize: '0.9rem' }}>{doc.description}</p>}
                <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                  <span style={{ background: '#f0f0f0', padding: '4px 10px', borderRadius: '4px', fontSize: '0.8rem', fontWeight: 600 }}>
                    {doc.typeDocument === 'COURS' ? '📚' : doc.typeDocument === 'EXERCISE' ? '🔢' : doc.typeDocument === 'PROJET' ? '🎯' : '📄'} {doc.typeDocument}
                  </span>
                  {doc.tags && doc.tags.split(',').map((tag, i) => (
                    <span key={i} style={{ background: '#e3f2fd', padding: '4px 10px', borderRadius: '4px', fontSize: '0.8rem', color: '#1976d2' }}>
                      {tag.trim()}
                    </span>
                  ))}
                </div>
              </div>

              <button
                onClick={() => handleDelete(doc.id)}
                style={{ padding: '8px 12px', background: '#fee', border: '1px solid #fcc', borderRadius: '6px', cursor: 'pointer', color: '#c33', fontWeight: 600 }}
              >
                <Trash2 size={16} />
              </button>
            </div>
          ))
        )}
      </div>

      <style jsx>{`
        .spinner {
          animation: spin 1s linear infinite;
        }
        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default DocumentsUploader;
